import SwiftUI

enum AgentforceSalesStudyBank {
    static let sections: [StudySection] = [
        // Sales Lifecycle (4 objectives, 29 topics)
        StudySection(
            id: "sales_lifecycle",
            title: "Sales Lifecycle",
            color: Color(red: 0.30, green: 0.50, blue: 0.80),
            lightColor: Color(red: 0.90, green: 0.94, blue: 1.00),
            icon: "chart.line.uptrend.xyaxis",
            objectives: [
                StudyObjective(
                    id: "sales_lifecycle_obj1",
                    title: "Given business requirements, metrics, key performance indicators (KPIs), or business challenges, determine the optimal solution in Sales Cloud",
                    topics: [
                        StudyTopic(id: "sales_lifecycle_obj1_q1", number: 1, question: "What is the difference between a sales KPI dashboard and a pipeline report in Salesforce, and when should each be used?", answer: "A KPI dashboard is a visual collection of dashboard components (charts, metrics, gauges) that display aggregated, real-time performance data across multiple dimensions — quota attainment, win rate, activity volume. It is designed for quick executive consumption and trend monitoring.\n\nA pipeline report is a tabular or summary report focused specifically on open opportunities grouped by stage, owner, close date, or amount. It is designed for operational review — helping managers and reps understand what deals exist, where they are, and what actions are needed.\n\nUse a KPI dashboard when the audience needs a high-level health check of sales performance. Use a pipeline report when the goal is deal-by-deal review, forecasting input, or identifying gaps in coverage."),
                        StudyTopic(id: "sales_lifecycle_obj1_q2", number: 2, question: "A company's sales leadership wants a single view of each sales rep's quota attainment, pipeline coverage, and activity levels. Which Sales Cloud feature set best supports this requirement?", answer: "The best feature combination is:\n\n- Collaborative Forecasting with quota management to show quota vs. committed/best-case pipeline per rep.\n\n- Reports and Dashboards with a dynamic dashboard (running as logged-in user or filtered by role) displaying pipeline coverage ratio and activity metrics.\n\n- Einstein Activity Capture or Activity Timeline to surface logged calls, emails, and meetings per rep.\n\n- Optionally, CRM Analytics (Tableau CRM) for richer multi-metric rep scorecards with drill-down capability.\n\nThe key is combining forecasting data (quota + pipeline) with activity data in a single dashboard view."),
                        StudyTopic(id: "sales_lifecycle_obj1_q3", number: 3, question: "A company tracks win rate, average deal size, and sales cycle length as core KPIs. Which Sales Cloud features should a consultant recommend to surface these metrics in real time for sales managers?", answer: "- Win Rate: Built using a Summary or Matrix report on Opportunities grouped by Stage, with a summary formula dividing Closed Won count by total Closed count.\n\n- Average Deal Size: Use a Summary report on Closed Won opportunities with the Average aggregation on the Amount field.\n\n- Sales Cycle Length: Requires a custom formula field on Opportunity calculating the difference between Close Date and Created Date (or a custom Start Date field), then aggregated in a Summary report.\n\nAll three can be surfaced as dashboard components for real-time visibility. For more complex trending, CRM Analytics allows time-series analysis without formula field workarounds."),
                        StudyTopic(id: "sales_lifecycle_obj1_q4", number: 4, question: "A company wants to measure pipeline health by comparing the number of new opportunities created versus opportunities closed each quarter. Which Salesforce tool is most appropriate for building this KPI?", answer: "A Summary or Matrix Report on Opportunities with:\n\n- A filter for the current quarter (using relative date filters: \"Created Date = This Quarter\" for new opps).\n\n- Grouped by Stage or Closed status to compare created vs. closed counts.\n\nThis can be displayed as a bar or combo chart on a dashboard. For trend-over-time comparison across multiple quarters, CRM Analytics is more capable, as native dashboards only show one time period at a time without custom workarounds."),
                        StudyTopic(id: "sales_lifecycle_obj1_q5", number: 5, question: "A VP of Sales wants to reduce the average sales cycle by identifying which deals are stalling. Which Sales Cloud feature best supports this requirement?", answer: "Einstein Opportunity Insights (part of Sales Cloud Einstein) can flag deals showing signs of inactivity or risk. Natively, a consultant can build:\n\n- A report on open opportunities filtered by \"Last Activity Date\" older than X days and \"Close Date approaching.\"\n\n- A Kanban view by stage to visually spot deals sitting too long in a stage.\n\n- Path with guidance to set expected stage duration benchmarks.\n\nFor proactive alerting, a Flow can send a notification to the manager when a deal has not had activity logged in a configurable number of days. Einstein Deal Insights provides AI-driven stall detection."),
                        StudyTopic(id: "sales_lifecycle_obj1_q6", number: 6, question: "A sales team reports that reps spend too much time on manual data entry after customer calls. Which Sales Cloud solution addresses this business challenge most directly?", answer: "Einstein Activity Capture (EAC) automatically logs emails and calendar events from Gmail or Outlook to the related Salesforce records, eliminating manual logging of those activity types.\n\nFor call-specific automation, Agentforce Sales Call Summaries (Einstein Conversation Insights) can transcribe calls and auto-generate call summaries and next-step tasks.\n\nSalesforce Inbox also helps reps log emails directly from their inbox with one click. Together, EAC and Einstein Conversation Insights are the most direct answer to reducing post-call data entry burden.")
                    ]
                ),
                StudyObjective(
                    id: "sales_lifecycle_obj2",
                    title: "Given a scenario, discuss common sales and marketing processes and anticipate key implementation considerations",
                    topics: [
                        StudyTopic(id: "sales_lifecycle_obj2_q1", number: 7, question: "A B2B company runs multi-touch marketing campaigns that feed leads into a qualification process before assigning them to reps. What implementation considerations should a consultant anticipate when mapping this process in Salesforce?", answer: "Key considerations:\n\n- Lead Status configuration: Define clear statuses (New, MQL, SAL, SQL, Disqualified) that map to each handoff stage.\n\n- Lead Assignment Rules: Automate routing from marketing to SDRs based on criteria (lead source, score, geography).\n\n- Campaign Member Status: Track engagement milestones so marketing can measure multi-touch attribution.\n\n- Lead Scoring integration: If using Pardot/Marketing Cloud Account Engagement, sync scores back to Salesforce as a field used in assignment logic.\n\n- SLA enforcement: Use Flows or Escalation Rules to alert managers if leads sit uncontacted past an agreed time window.\n\n- Duplicate management: Enable matching and duplicate rules to prevent the same lead entering multiple times from different campaigns."),
                        StudyTopic(id: "sales_lifecycle_obj2_q2", number: 8, question: "What are the key considerations when integrating a marketing automation platform with Salesforce for lead handoff to sales?", answer: "- Sync direction and triggers: Determine which system is the master for lead records and when records sync (real-time vs. scheduled batch).\n\n- Field mapping: Ensure lead score, campaign source, and qualification fields map cleanly between systems.\n\n- Duplicate prevention: Use Salesforce matching rules or the MAP's deduplication logic to avoid creating duplicate leads or contacts.\n\n- Lead status alignment: Marketing and sales must agree on what status values trigger the handoff (e.g., \"MQL\" moves the lead to a sales queue).\n\n- Campaign attribution: Ensure campaign member records are created in Salesforce so influence reporting is accurate.\n\n- Error handling: Define what happens when a sync fails — does the record queue for retry, or does it alert an admin?"),
                        StudyTopic(id: "sales_lifecycle_obj2_q3", number: 9, question: "A company wants to ensure that only qualified leads meeting a minimum lead score threshold are converted to opportunities. Which Salesforce mechanism best enforces this business rule?", answer: "A Validation Rule on the Lead object that prevents conversion when the lead score field is below the defined threshold. The rule fires when a rep attempts to convert, blocking the action and displaying a descriptive error message.\n\nAlternatively, a Flow triggered on lead conversion can check the score and either block or redirect the action. For a softer approach, Path guidance on the Lead record can display warnings without hard enforcement. The validation rule is the most direct, declarative enforcement mechanism."),
                        StudyTopic(id: "sales_lifecycle_obj2_q4", number: 10, question: "A company's inside sales team works inbound leads while the field sales team handles strategic accounts. What implementation considerations arise when configuring a single Salesforce org to support both motions?", answer: "- Record Types: Use separate record types for inbound leads vs. strategic account opportunities to apply different page layouts, fields, and picklist values.\n\n- Sales Processes: Define distinct opportunity stage progressions for transactional (short-cycle) vs. strategic (long-cycle) deals.\n\n- Lead Assignment: Route inbound leads to inside sales queues; field sales works from Account and Contact records, not Lead queues.\n\n- Forecasting: Consider separate forecast categories or hierarchy branches for inside vs. field sales to avoid mixing their pipelines.\n\n- Activity and Cadence tools: Inside sales may use Sales Engagement (cadences); field sales may rely on manual relationship management.\n\n- Role Hierarchy: Structure roles so managers see only their team's pipeline, with a shared executive view at the top."),
                        StudyTopic(id: "sales_lifecycle_obj2_q5", number: 11, question: "A company has both a transactional sales cycle (days) and a strategic sales cycle (months). What considerations should a consultant apply when designing opportunity stages to support both motions?", answer: "- Separate Sales Processes: Create two Sales Processes in Salesforce — one with fewer, faster stages for transactional deals and one with more detailed stages for strategic deals.\n\n- Record Types: Map each Sales Process to a distinct Opportunity Record Type so reps select the right process at creation.\n\n- Stage Probability: Set realistic probability values per stage in each process so forecasting rollups are accurate.\n\n- Required Fields by Stage: Use Path or validation rules to enforce different exit criteria per process without over-burdening transactional reps.\n\n- Reporting: Segment reports by record type to avoid mixing cycle-length metrics between the two motions."),
                        StudyTopic(id: "sales_lifecycle_obj2_q6", number: 12, question: "A company runs account-based marketing (ABM) campaigns and wants to tie marketing activity directly to revenue outcomes. Which Salesforce feature set supports this alignment?", answer: "- Campaigns and Campaign Influence: Associate campaign activity with opportunities to track which marketing touches contributed to revenue.\n\n- Campaign Hierarchy: Group ABM campaigns under a parent (e.g., by target account segment) to roll up ROI metrics.\n\n- Einstein Campaign Influence (if licensed): Uses AI to assign attribution credit across multiple campaigns that touched an opportunity.\n\n- Account-level Campaign Members: Add Contacts from target accounts as campaign members to track engagement at the account level.\n\n- Reports: Build Opportunity with Campaign Influence reports to show revenue influenced by specific ABM campaigns. This connects marketing investment directly to Closed Won amounts.")
                    ]
                ),
                StudyObjective(
                    id: "sales_lifecycle_obj3",
                    title: "Identify when to use Sales Cloud features and related products such as Sales Engagement, Salesforce Inbox, Enterprise Territory Management, Opportunity Forecasting, Sales Cloud Einstein, and generative/predictive AI",
                    topics: [
                        StudyTopic(id: "sales_lifecycle_obj3_q1", number: 13, question: "What is the difference between Collaborative Forecasting and Territory-based Forecasting in Salesforce, and when should each be used?", answer: "Collaborative Forecasting rolls up opportunity amounts through the role hierarchy. Each manager's forecast includes their own pipeline plus their subordinates'. Reps and managers can submit forecast adjustments. Best used when forecasting is organized by sales team reporting structure.\n\nTerritory Forecasting (within Enterprise Territory Management) rolls up opportunities based on territory assignment rather than record ownership. An opportunity can belong to multiple territories, and each territory manager forecasts their territory's pipeline independently of who owns the record.\n\nUse Collaborative Forecasting for most orgs. Use Territory Forecasting when deals are managed by territory model and a rep may cover multiple territories — or when account coverage doesn't map cleanly to the role hierarchy."),
                        StudyTopic(id: "sales_lifecycle_obj3_q2", number: 14, question: "A large enterprise has hundreds of sales territories that overlap by geography, product line, and vertical. Which Salesforce feature is designed to manage this complexity?", answer: "Enterprise Territory Management (ETM). It supports multiple territory models, overlapping territory assignments, territory types (by geo, product, vertical), and territory hierarchies. Assignment rules automatically assign accounts and their opportunities to the correct territories. ETM also integrates with Opportunity Forecasting so each territory rolls up its own pipeline. It is the only native Salesforce feature designed for complex, multi-dimensional territory structures."),
                        StudyTopic(id: "sales_lifecycle_obj3_q3", number: 15, question: "A company wants to automate outreach cadences for SDRs, including templated emails and call tasks at defined intervals. Which Sales Cloud product best supports this requirement?", answer: "Sales Engagement (formerly High Velocity Sales). It provides:\n\n- Cadences: Multi-step automated outreach sequences combining email steps, call tasks, LinkedIn tasks, and wait steps.\n\n- Work Queue: A prioritized task queue that surfaces the next action for each rep each day.\n\n- Email Templates: Standardized templates used within cadence steps.\n\n- Engagement tracking: Opens, clicks, and replies are tracked to measure cadence effectiveness.\n\nSales Engagement is purpose-built for high-volume, structured SDR outreach and is far more scalable than manually created task workflows."),
                        StudyTopic(id: "sales_lifecycle_obj3_q4", number: 16, question: "When should a consultant recommend Sales Engagement over a standard Salesforce task-based workflow for sales outreach?", answer: "Recommend Sales Engagement when:\n\n- SDRs or BDRs need structured, repeatable multi-step outreach sequences.\n\n- The team sends high volumes of outreach and needs a prioritized work queue.\n\n- Outreach effectiveness (open rates, response rates) needs to be tracked at the cadence/step level.\n\n- Consistent outreach standards need to be enforced across the team.\n\nA standard task-based workflow is sufficient when outreach is low volume, unstructured, or rep-driven without a need for sequence enforcement or engagement analytics."),
                        StudyTopic(id: "sales_lifecycle_obj3_q5", number: 17, question: "A company wants its sales reps to log emails and calendar events from Outlook automatically into Salesforce without switching applications. Which product addresses this need?", answer: "Einstein Activity Capture (EAC) automatically syncs emails and calendar events from Microsoft Exchange/Outlook (or Google) to Salesforce, associating them with matching Lead, Contact, Account, and Opportunity records. No manual logging is required for routine email and meeting activity.\n\nSalesforce Inbox is a complementary tool that adds a Salesforce sidebar directly within Outlook or Gmail, allowing reps to view and edit Salesforce records, insert availability links, and log emails manually with more control than EAC alone."),
                        StudyTopic(id: "sales_lifecycle_obj3_q6", number: 18, question: "A company wants to use Einstein Activity Capture to log rep activities. What is a key limitation the consultant should communicate to stakeholders?", answer: "The most critical limitation: EAC activity data is not stored as standard Salesforce Task or Event records. Instead, activities synced by EAC are stored in a separate data store and displayed via the Activity Timeline component. This means:\n\n- EAC-logged activities cannot be used in standard Salesforce reports directly.\n\n- They are not visible in the standard Activities related list.\n\n- SOQL queries and Flows cannot natively access EAC activity data.\n\n- Data retention for EAC activities is limited (typically 6 months by default).\n\nThis is a major consideration for customers who want to report on or automate based on email/meeting activity."),
                        StudyTopic(id: "sales_lifecycle_obj3_q7", number: 19, question: "A company wants to identify which open opportunities are most likely to close based on historical patterns. Which Sales Cloud Einstein feature addresses this?", answer: "Einstein Opportunity Scoring. It uses machine learning trained on the org's own closed opportunity history to assign each open opportunity a score from 1-99. The score reflects the likelihood of closing based on factors like deal age, activity patterns, stage, amount, and engagement signals. Scores surface in the Opportunity record and list views, helping reps and managers prioritize their pipeline."),
                        StudyTopic(id: "sales_lifecycle_obj3_q8", number: 20, question: "A company wants to surface next-best-action recommendations to reps during active deals. Which AI feature in Sales Cloud supports this?", answer: "Einstein Next Best Action (NBA). It uses recommendation strategies (built with Flow or Apex) combined with Einstein prediction models to surface contextual action suggestions on any Salesforce record page. For example, a rep viewing an opportunity in the Negotiation stage might see a recommendation to \"Schedule an executive sponsor call\" or \"Send a case study\" based on deal characteristics and historical patterns."),
                        StudyTopic(id: "sales_lifecycle_obj3_q9", number: 21, question: "A company wants to generate a call summary and recommended follow-up actions automatically after each sales call. Which Sales Cloud feature supports this use case?", answer: "Einstein Conversation Insights (now part of Agentforce for Sales). It transcribes recorded sales calls, identifies key topics and keywords, generates a call summary, and can suggest follow-up tasks — all surfaced on the related Salesforce record after the call. It requires call recording integration (e.g., via supported telephony partners or Salesforce-native Dialer). The AI-generated summary eliminates manual note-taking and ensures consistent call logging.")
                    ]
                ),
                StudyObjective(
                    id: "sales_lifecycle_obj4",
                    title: "Identify ways to transform business outcomes and sales KPIs into reports and dashboards",
                    topics: [
                        StudyTopic(id: "sales_lifecycle_obj4_q1", number: 22, question: "How are summary formula fields in Salesforce reports used to surface calculated KPIs?", answer: "Summary formula fields are custom calculated columns added to Summary or Matrix reports. They perform math on summary-level values (Sum, Average, Count, Max, Min) across grouped data. Examples:\n\n- Win Rate: `Closed_Won_Count / Total_Closed_Count * 100`\n\n- Pipeline Coverage Ratio: `Open_Pipeline_Amount / Quota_Amount`\n\n- Average Deal Size: Built-in Average aggregation, or a formula dividing total amount by count.\n\nThey are evaluated at each grouping level (subtotal and grand total) and can reference other summary fields. They are not stored on records — they exist only within the report."),
                        StudyTopic(id: "sales_lifecycle_obj4_q2", number: 23, question: "A sales director wants a dashboard showing top 10 deals by amount. What report type should a consultant configure?", answer: "A Tabular report on Opportunities with:\n\n- Sorted by Amount descending.\n\n- Row limit set to 10 (using the \"Add Row Limit\" option — required to use a tabular report as a dashboard source).\n\n- Filtered to Open opportunities or a specific time period.\n\nThe dashboard component type should be a table or bar chart. The row limit is essential — without it, tabular reports cannot be added to dashboards."),
                        StudyTopic(id: "sales_lifecycle_obj4_q3", number: 24, question: "A sales director wants a dashboard showing current quarter pipeline by stage. What report type should a consultant configure?", answer: "A Summary report on Opportunities grouped by Stage, filtered by:\n\n- Close Date = Current FQ (fiscal quarter).\n\n- Stage excludes Closed Won and Closed Lost (or includes all for a full view).\n\nDisplay as a stacked bar chart or donut chart on the dashboard, using Amount (Sum) as the measure. This gives a visual breakdown of pipeline dollars distributed across stages."),
                        StudyTopic(id: "sales_lifecycle_obj4_q4", number: 25, question: "A sales director wants a dashboard showing forecast vs. quota. What report type should a consultant configure?", answer: "A Summary report using the Forecasting Items or Opportunities with Forecasting report type (if Collaborative Forecasting is enabled). Group by Owner or Role and show:\n\n- Committed forecast amount vs. quota amount.\n\nAlternatively, use a Quotas report joined with a pipeline report in CRM Analytics for side-by-side comparison. Natively, a metric or gauge dashboard component can show one rep's forecast vs. quota; a bar chart works for a team view. Note: quota data requires the Forecasting Quota object to be populated."),
                        StudyTopic(id: "sales_lifecycle_obj4_q5", number: 26, question: "A sales ops team wants to create a dashboard visible to all sales reps showing only their own data. Which dashboard feature in Salesforce enables this?", answer: "Dynamic Dashboards. Set the dashboard to run as \"The logged-in user\" instead of a specific user. Each rep who views the dashboard sees data filtered to their own records based on their security context. The number of dynamic dashboards per org is limited by edition (e.g., up to 10 for Enterprise, up to 5 for Professional)."),
                        StudyTopic(id: "sales_lifecycle_obj4_q6", number: 27, question: "A company wants to track the conversion rate from lead to opportunity to closed-won across different marketing campaigns. Which reporting approach in Salesforce supports this end-to-end funnel view?", answer: "Use a combination of:\n\n- Leads with Converted Lead Information report type to track lead-to-opportunity conversion rates by campaign.\n\n- Opportunities with Campaign Influence report type to see which campaigns influenced Closed Won revenue.\n\n- A Campaign ROI report for a summary of leads generated, converted, and associated revenue per campaign.\n\nFor a true end-to-end funnel visualization, CRM Analytics with a funnel chart is more powerful than native reports, which cannot natively display a multi-stage conversion funnel in one view."),
                        StudyTopic(id: "sales_lifecycle_obj4_q7", number: 28, question: "A company wants its sales managers to receive a weekly email of open opportunities approaching their expected close date. Which Salesforce feature fulfills this requirement without custom development?", answer: "Report Subscriptions. A manager can subscribe to a saved Opportunity report (filtered to their team's open opportunities approaching close date) and set a delivery schedule (e.g., every Monday at 8am). The report is emailed as a formatted result set or attached as XLS/CSV. No code required. The subscription can also be set to trigger only when report results meet a condition (e.g., \"when record count is greater than 0\")."),
                        StudyTopic(id: "sales_lifecycle_obj4_q8", number: 29, question: "When should a consultant recommend CRM Analytics (Tableau CRM) dashboards over native Salesforce reports and dashboards?", answer: "Recommend CRM Analytics when:\n\n- The org needs multi-object, cross-dataset analysis that native report types cannot join.\n\n- Large data volumes make native reports slow or hit row limits (native reports cap at 2,000 rows displayed, 100,000 in export).\n\n- The team needs time-series trending, predictive analytics, or Einstein Discovery insights embedded in dashboards.\n\n- Advanced visualizations (funnel charts, geo maps, custom layouts) are required.\n\n- Data from external systems needs to be blended with Salesforce data in one view.\n\nNative reports and dashboards are sufficient for most standard use cases and require no additional license.")
                    ]
                )
            ]
        ),

        // Consulting and Implementation Strategies (5 objectives, 31 topics)
        StudySection(
            id: "consulting_impl",
            title: "Consulting and Implementation Strategies",
            color: Color(red: 0.20, green: 0.60, blue: 0.50),
            lightColor: Color(red: 0.88, green: 0.96, blue: 0.94),
            icon: "person.2.fill",
            objectives: [
                StudyObjective(
                    id: "consulting_impl_obj1",
                    title: "Prior to an implementation, assess user experience, the communication plan, training, and change management, and establish metrics that measure success",
                    topics: [
                        StudyTopic(id: "consulting_impl_obj1_q1", number: 30, question: "A company is beginning a Sales Cloud implementation. What change management activities should a consultant recommend before go-live to maximize adoption?", answer: "- Stakeholder alignment: Secure executive sponsor commitment and ensure leadership visibly endorses the new system.\n\n- Champion network: Identify and train super-users across teams and regions who will support peers post-launch.\n\n- Current-state assessment: Document existing workflows, pain points, and informal workarounds to ensure the new system addresses real needs.\n\n- Communication plan: Deliver phased communications explaining the \"why,\" timeline, and what changes for each audience.\n\n- Training plan: Design role-based training tailored to actual daily tasks, not feature overviews.\n\n- Success metrics: Define adoption KPIs (login rates, data completeness, activity logging) so progress is measurable from day one.\n\n- Feedback channels: Establish a way for users to raise issues early (e.g., a Chatter group, Slack channel, or help desk queue)."),
                        StudyTopic(id: "consulting_impl_obj1_q2", number: 31, question: "A company has historically low CRM adoption. What pre-implementation UX assessment activities should a consultant perform to address this risk?", answer: "- User interviews and surveys: Understand why the previous system was not used — was it complexity, lack of value, or lack of enforcement?\n\n- Shadowing sessions: Observe reps in their actual workflow to identify friction points and workarounds.\n\n- Process mapping: Document the current-state sales process to ensure Salesforce mirrors how people actually work rather than how leadership thinks they work.\n\n- Persona analysis: Identify distinct user types (SDR, AE, manager, ops) and their different needs and pain points.\n\n- UX prototyping: Present wireframes or sandbox demos to key users before build to validate that the design reduces, not adds, friction.\n\nThe goal is to ensure the configured solution fits the users' reality, which is the most direct driver of adoption."),
                        StudyTopic(id: "consulting_impl_obj1_q3", number: 32, question: "A stakeholder group includes executive sponsors, frontline managers, and end users. How should a communication plan differ for each group during a Sales Cloud implementation?", answer: "- Executive Sponsors: Focus on business outcomes, ROI, milestone progress, and risk flags. Communication is infrequent (monthly steering updates), high-level, and tied to strategic goals. They need to visibly champion the project.\n\n- Frontline Managers: Focus on how their team's workflow changes, what reporting and visibility they will gain, and how to coach reps using the new tools. Weekly or bi-weekly updates with process details.\n\n- End Users (Reps): Focus on \"what's in it for me\" — how the tool makes their job easier, what is changing in their daily tasks, and where to get help. Frequent, simple, task-oriented communications closer to go-live. Use demos, quick-reference guides, and peer champions.\n\nOne-size-fits-all communications are a leading cause of adoption failure."),
                        StudyTopic(id: "consulting_impl_obj1_q4", number: 33, question: "A consultant is designing the training plan for a Sales Cloud rollout to 200 reps across three regions. What factors should drive the training strategy?", answer: "- Role-based content: Train reps on their specific daily tasks (not all features). Separate sessions for SDRs, AEs, and managers.\n\n- Region and time zone logistics: Schedule sessions across time zones; consider recorded content for async consumption.\n\n- Learning modalities: Mix live instructor-led sessions for critical workflows with on-demand Trailhead modules and quick-reference job aids for reinforcement.\n\n- Hands-on practice: Use sandbox training environments so reps practice on real-feeling data before going live.\n\n- Timing: Train close to go-live (within 1-2 weeks) to minimize knowledge decay.\n\n- Super-user support: Trained champions in each region answer day-one questions without requiring all queries to go to the consultant.\n\n- Ongoing reinforcement: Schedule refresher sessions 30 and 60 days post-launch based on observed gaps."),
                        StudyTopic(id: "consulting_impl_obj1_q5", number: 34, question: "What is the role of a super-user or champion network in a Sales Cloud implementation, and when should it be established?", answer: "Super-users (champions) are power users within each team or region who receive deeper training, participate in UAT, and serve as the first line of peer support after go-live. Their roles:\n\n- Answer day-to-day questions from teammates.\n\n- Collect and triage feedback to the project team.\n\n- Model correct system usage behavior for peers.\n\n- Reduce support burden on the consulting team post-launch.\n\nThe champion network should be identified and onboarded during the design or build phase — not at go-live. They need time to build confidence and familiarity before they support others."),
                        StudyTopic(id: "consulting_impl_obj1_q6", number: 35, question: "What metrics should a consultant recommend to measure success in the first 90 days after a Sales Cloud go-live?", answer: "Adoption metrics:\n\n- Daily/weekly login rate by user segment.\n\n- Percentage of opportunities with required fields populated.\n\n- Activity logging rate (calls, emails, meetings) per rep per week.\n\nProcess metrics:\n\n- Lead response time (time from creation to first contact attempt).\n\n- Opportunity stage progression rates.\n\n- Quote generation time.\n\nBusiness outcome metrics:\n\n- Pipeline coverage vs. prior period.\n\n- Forecast accuracy vs. actual close.\n\n- Win rate trend (though 90 days may be too early for meaningful change).\n\nDefine baselines before go-live so you have a comparison point.")
                    ]
                ),
                StudyObjective(
                    id: "consulting_impl_obj2",
                    title: "During an implementation, outline and apply appropriate deployment considerations",
                    topics: [
                        StudyTopic(id: "consulting_impl_obj2_q1", number: 36, question: "What are the key differences between a phased rollout and a big-bang deployment, and when should each be used in a Sales Cloud implementation?", answer: "Big-bang deployment: All users and features go live simultaneously on a single cutover date. Simpler to plan, but higher risk. Best when the org is small, the solution is straightforward, or the business cannot support a prolonged parallel-run period.\n\nPhased rollout: Releases functionality or user groups incrementally. Lower risk because issues surface in a smaller user population first. Best for large, complex orgs; geographically dispersed teams; or when the full feature set cannot be ready simultaneously.\n\nUse phased rollout when risk mitigation and change management bandwidth are concerns. Use big-bang when speed-to-value, contract deadlines, or organizational simplicity favor it."),
                        StudyTopic(id: "consulting_impl_obj2_q2", number: 37, question: "A company is migrating from a sandbox to production for a Sales Cloud go-live. What deployment considerations should the consultant address to minimize risk?", answer: "- Change Sets or DevOps tooling: Package all metadata components systematically; avoid manual production edits.\n\n- Deployment order: Deploy in the correct dependency sequence (custom objects before page layouts, permission sets before assignments).\n\n- Data migration timing: Load production data as close to go-live as possible to minimize staleness; run a final delta load if needed.\n\n- Validation in Full Sandbox: Run a full deployment test in a sandbox that mirrors production before the real cutover.\n\n- Rollback plan: Document which components can be reverted quickly if critical issues emerge post-deployment.\n\n- Communication: Notify users of the maintenance window and expected impact.\n\n- Post-deployment smoke testing: Execute a checklist of critical user workflows immediately after deployment before opening access."),
                        StudyTopic(id: "consulting_impl_obj2_q3", number: 38, question: "A consultant needs to deploy configuration changes including custom fields, page layouts, validation rules, and workflow rules to production. Which deployment approach is most appropriate and why?", answer: "Change Sets (for teams without a full DevOps pipeline) or Salesforce DX with a CI/CD pipeline (for mature DevOps practices).\n\nChange Sets are the standard declarative option: build in sandbox, add components to an outbound change set, upload to production, validate (which runs Apex tests), then deploy.\n\nWhy not manual production edits? Direct production configuration bypasses sandbox testing, creates environment drift, and is not auditable. All changes should follow the sandbox-to-production path.\n\nFor complex orgs with frequent deployments, Copado or similar DevOps tooling provides version control, conflict detection, and automated deployment pipelines beyond what Change Sets offer."),
                        StudyTopic(id: "consulting_impl_obj2_q4", number: 39, question: "What testing activities should a consultant conduct during a Sales Cloud implementation before promoting changes to production?", answer: "- Unit testing: Verify individual configurations (validation rules, workflows, flows) behave as expected in isolation.\n\n- Integration testing: Test end-to-end process flows (e.g., lead conversion through opportunity creation and quote generation).\n\n- User Acceptance Testing (UAT): Have business users test real-world scenarios using their own data in the sandbox; document and resolve issues.\n\n- Regression testing: After fixing UAT issues, retest previously passing scenarios to confirm nothing broke.\n\n- Performance testing: Test with representative data volumes, especially for reports and LDV scenarios.\n\n- Security testing: Verify that OWD, sharing rules, and permission sets enforce the correct access model for each persona.\n\n- Apex test coverage: Ensure all Apex code meets the 75% coverage requirement (though 90%+ is the best practice) before deploying to production."),
                        StudyTopic(id: "consulting_impl_obj2_q5", number: 40, question: "A company wants to do a pilot rollout of Sales Cloud to one sales region before expanding company-wide. What implementation considerations should guide this approach?", answer: "- Region selection: Choose a region that is representative of the broader business but not so critical that failures would have catastrophic impact.\n\n- Scope clarity: Define clearly what is in vs. out of scope for the pilot (which features, which object types, which integrations).\n\n- Data isolation: Ensure pilot users' data does not conflict with or overwrite data that non-pilot users are still managing in legacy systems.\n\n- Feedback loops: Establish structured feedback mechanisms (weekly check-ins, issue logs) to capture learnings during the pilot.\n\n- Success criteria: Define what \"successful\" means for the pilot before it starts, so the expansion decision is objective.\n\n- Timeline buffer: Allow adequate time between pilot go-live and company-wide rollout to incorporate learnings without delaying the broader launch.")
                    ]
                ),
                StudyObjective(
                    id: "consulting_impl_obj3",
                    title: "Post implementation, determine how to respond to low adoption, changing business requirements, and user access, and plan for continuous improvement",
                    topics: [
                        StudyTopic(id: "consulting_impl_obj3_q1", number: 41, question: "What governance structure should a consultant recommend to manage ongoing configuration changes and user access in a production Sales Cloud org?", answer: "- Salesforce Center of Excellence (CoE) or an internal Admin team as the gatekeeper for production changes.\n\n- Change Request Process: A formal intake process (ticketing system or Salesforce-native case queue) for users to submit configuration requests.\n\n- Release cadence: Scheduled deployment windows (e.g., bi-weekly or monthly) to batch non-urgent changes, reducing deployment risk.\n\n- Change Advisory Board (CAB): A cross-functional group (Sales Ops, IT, Sales leadership) that reviews and prioritizes requests.\n\n- User access reviews: Quarterly audits of permission sets, roles, and profile assignments.\n\n- Documentation: Maintain an org configuration log and data dictionary in a shared wiki or document repository.\n\nWithout governance, orgs accumulate technical debt through ad-hoc production changes."),
                        StudyTopic(id: "consulting_impl_obj3_q2", number: 42, question: "What metrics and review cadences should a consultant establish to support continuous improvement after a Sales Cloud implementation?", answer: "Weekly: Login rates, activity logging volume, pipeline update completeness — reviewed by Sales Ops.\n\nMonthly: Forecast accuracy, field completion rates on key objects, open support tickets related to CRM issues — reviewed with Sales leadership.\n\nQuarterly: Win rate trends, adoption KPI progress vs. baseline, user satisfaction surveys, backlog prioritization for new features or enhancements.\n\nAnnually: Full ROI assessment comparing business outcomes (revenue, sales cycle, win rate) to pre-implementation baselines.\n\nPair metrics with structured review meetings so findings drive action, not just reporting."),
                        StudyTopic(id: "consulting_impl_obj3_q3", number: 43, question: "Six months after go-live, a Sales Cloud implementation shows low login rates and incomplete opportunity records. What steps should a consultant recommend to diagnose and address adoption issues?", answer: "Diagnose:\n\n- Pull login history reports and identify which user segments are not logging in.\n\n- Run data completeness reports on Opportunity required fields to identify patterns by team, region, or manager.\n\n- Conduct user interviews to understand perceived barriers (\"it takes too long,\" \"I don't see the value,\" \"my manager doesn't check it\").\n\nAddress:\n\n- Engage executive sponsors to reinforce expectation that Salesforce is the system of record.\n\n- Simplify page layouts and remove fields reps don't use.\n\n- Implement manager accountability: managers should review and discuss pipeline in Salesforce during 1:1s.\n\n- Provide targeted retraining for specific gaps rather than a generic \"re-onboarding.\"\n\n- Consider automation (Flows, EAC) to reduce manual entry burden."),
                        StudyTopic(id: "consulting_impl_obj3_q4", number: 44, question: "A company's sales process changes significantly after go-live, requiring new stages, fields, and approval workflows. How should a consultant manage these changing business requirements post-implementation?", answer: "- Document the request: Capture the new requirements formally, including the business reason and impacted users.\n\n- Impact assessment: Evaluate what existing records, reports, automations, and integrations will be affected by stage or field changes (e.g., changing stage picklist values affects existing reports and history).\n\n- Sandbox development: Build and test all changes in a sandbox before deploying.\n\n- Data migration for existing records: Determine whether existing open opportunities need their stages or field values updated to match the new process.\n\n- Communication and retraining: Notify affected users of changes and update training materials.\n\n- Governance approval: Route the change through the CAB or change request process before any production deployment."),
                        StudyTopic(id: "consulting_impl_obj3_q5", number: 45, question: "A company reports that certain reps can see opportunities they should not have access to after go-live. What is the recommended first step to diagnose this access issue?", answer: "Use \"Why can this user see this record?\" — accessible via the sharing button on a record or via the User Access Summary in Setup (Salesforce introduced a unified access summary in recent releases). This shows exactly which rule (OWD, role hierarchy, sharing rule, manual share, team membership, or territory) granted access to the specific record.\n\nFrom there, identify whether the unintended access is coming from an overly broad sharing rule, incorrect role hierarchy placement, Account/Opportunity Team membership, or an OWD setting that is more permissive than intended.")
                    ]
                ),
                StudyObjective(
                    id: "consulting_impl_obj4",
                    title: "Leverage the project management lifecycle to deliver a successful solution on time and within scope",
                    topics: [
                        StudyTopic(id: "consulting_impl_obj4_q1", number: 46, question: "What are the key deliverables at each phase of a typical Salesforce implementation project lifecycle (discovery, design, build, test, deploy, hypercare)?", answer: "- Discovery: Business Requirements Document (BRD), process maps, current-state assessment, stakeholder register, project charter.\n\n- Design: Solution Design Document (SDD), data model diagram, security model design, integration architecture, UX wireframes.\n\n- Build: Configured sandbox, Apex/Flow components, data migration scripts, integration connections, training materials (draft).\n\n- Test: UAT test scripts, UAT sign-off document, defect log, test completion report.\n\n- Deploy: Deployed production org, cutover checklist, data load completion confirmation, go-live communication sent.\n\n- Hypercare: Issue log, daily/weekly triage calls, adoption tracking report, admin handoff documentation."),
                        StudyTopic(id: "consulting_impl_obj4_q2", number: 47, question: "What is the purpose of a RACI matrix in a Salesforce implementation project, and who typically owns which activities?", answer: "A RACI matrix defines who is Responsible (does the work), Accountable (owns the outcome), Consulted (provides input), and Informed (kept updated) for each project activity. It prevents ambiguity, clarifies decision authority, and ensures no task is unowned.\n\nTypical ownership:\n\n- Discovery/Requirements: Consultant leads (Responsible), Client Business Owner (Accountable).\n\n- Configuration/Build: Consultant (Responsible), Project Manager (Accountable).\n\n- UAT: Client users (Responsible), Client Project Lead (Accountable), Consultant (Consulted).\n\n- Deployment approval: Client executive sponsor (Accountable), Consultant (Responsible for execution).\n\n- Training: Consultant designs (Responsible), Client HR/Ops (Accountable for delivery)."),
                        StudyTopic(id: "consulting_impl_obj4_q3", number: 48, question: "A Sales Cloud project is at risk of scope creep as stakeholders add new requirements during the build phase. What project management techniques should a consultant apply?", answer: "- Change Control Process: Require all new requests to go through a formal change request form, impact assessment (time, cost, risk), and sponsor approval before being added to scope.\n\n- Reference the SOW: Revisit the Statement of Work to distinguish what was agreed vs. what is new.\n\n- Parking Lot: Document new ideas in a backlog or \"Phase 2\" list to acknowledge them without committing to current-phase delivery.\n\n- MoSCoW prioritization: If some new requirements must be included, formally deprioritize (or remove) existing scope to maintain timeline and budget.\n\n- Stakeholder communication: Escalate to the executive sponsor when cumulative scope additions threaten the go-live date or budget."),
                        StudyTopic(id: "consulting_impl_obj4_q4", number: 49, question: "A Sales Cloud project has a fixed deadline but requirements are still being finalized by the client. How should a consultant handle this tension to keep the project on track?", answer: "- Time-box discovery: Set a hard deadline for requirements finalization and communicate that any requirements received after that date are candidates for Phase 2.\n\n- MVP scoping: Work with the client to define the minimum viable set of requirements needed for go-live. Everything else goes to backlog.\n\n- Risk log: Document the risk that incomplete requirements may lead to rework, and get client sign-off on the risk and mitigation plan.\n\n- Parallel workstreams: Begin building on confirmed requirements while discovery continues for remaining areas.\n\n- Executive escalation: If the client is unable to finalize requirements, escalate to the project sponsor to drive internal decisions."),
                        StudyTopic(id: "consulting_impl_obj4_q5", number: 50, question: "A consultant needs to escalate a risk that could derail the go-live timeline. What is the appropriate escalation path and communication approach?", answer: "- Document first: Add the risk to the project risk register with probability, impact rating, and proposed mitigation.\n\n- Escalate to the Project Manager first, who escalates to the Steering Committee or executive sponsor if the risk is at the project level.\n\n- Communication approach: Be factual and solution-oriented. Present the risk, its potential impact (delay, cost, quality), and 2-3 mitigation options with a recommendation. Avoid blame.\n\n- Timing: Escalate early — as soon as the risk is identified, not after it becomes an issue. Giving stakeholders lead time preserves their options for mitigation.\n\n- Written record: Follow up verbal escalation with a written summary (email or risk register update) so the escalation is documented.")
                    ]
                ),
                StudyObjective(
                    id: "consulting_impl_obj5",
                    title: "Conduct discovery workshops, analyze business requirements, define solutions, and prioritize use cases",
                    topics: [
                        StudyTopic(id: "consulting_impl_obj5_q1", number: 51, question: "What is the difference between a functional requirement and a technical requirement in a Sales Cloud implementation, and how should each be documented?", answer: "Functional requirement: Describes what the system must do from a business perspective. Written in business language, tied to a user story or business process. Example: \"Sales managers must be able to view all open opportunities for their team sorted by close date.\"\n\nTechnical requirement: Describes how the system must be built to satisfy the functional requirement. Includes specifics about configuration, integration, security, or code. Example: \"Role hierarchy with Manager role above Rep role; OWD for Opportunities set to Private.\"\n\nDocumentation: Functional requirements are captured in a BRD or user story backlog, prioritized with business stakeholders. Technical requirements are captured in the Solution Design Document (SDD), owned by the consultant/architect. Traceability between the two should be maintained."),
                        StudyTopic(id: "consulting_impl_obj5_q2", number: 52, question: "How should a consultant use a process map or swim-lane diagram during discovery to clarify handoffs between marketing, inside sales, and field sales?", answer: "A swim-lane diagram maps each team's actions as horizontal lanes with process steps flowing left to right. Handoff points are where activity crosses from one lane to another — these are the highest-risk points for confusion, delay, or dropped work.\n\nDuring discovery, walk through the diagram with representatives from each team to:\n\n- Confirm each step is accurate.\n\n- Identify who actually makes the decision vs. who thinks they do.\n\n- Surface unofficial handoff criteria (\"we actually wait for X before passing it over\").\n\n- Highlight gaps where there is no defined owner.\n\nThe swim-lane becomes the foundation for configuring assignment rules, lead status transitions, and notification workflows in Salesforce."),
                        StudyTopic(id: "consulting_impl_obj5_q3", number: 53, question: "A consultant is leading a discovery workshop with a sales team that has conflicting priorities across regions. How should the consultant facilitate the session to reach alignment on requirements?", answer: "- Set ground rules upfront: Agree that the goal is a shared solution, not a regional win. The facilitator remains neutral.\n\n- Use structured exercises: Instead of open debate, use techniques like dot voting, affinity mapping, or MoSCoW prioritization on sticky notes/whiteboard so all voices contribute equally.\n\n- Focus on shared goals: Anchor disagreements back to the common business objective (e.g., \"which option gets us to the revenue goal faster?\").\n\n- Document all positions: Record minority opinions in a \"parking lot\" so stakeholders feel heard even if their position does not prevail.\n\n- Escalate when stuck: If two regions cannot align on a requirement, escalate to the executive sponsor for a decision rather than letting the workshop stall.\n\n- Time-box discussions: Prevent any single debate from consuming the entire session."),
                        StudyTopic(id: "consulting_impl_obj5_q4", number: 54, question: "What techniques should a consultant use during a discovery workshop to surface implicit business requirements that stakeholders have not explicitly stated?", answer: "- \"Five Whys\": Ask \"why\" repeatedly to get below the surface request to the underlying need.\n\n- Scenario walkthroughs: \"Walk me through what happens when a rep gets a lead from an event\" — narratives reveal implicit steps.\n\n- Edge case probing: \"What happens if the deal is over $1M? What if the customer is international?\" — edge cases surface hidden requirements.\n\n- Observation: Shadow users in their actual workflow rather than relying solely on what they say in a workshop.\n\n- Reverse questioning: \"What would make this solution fail?\" surfaces constraints and non-negotiables stakeholders wouldn't think to mention.\n\n- Show, don't tell: Demo a prototype or existing Salesforce feature — seeing a solution often triggers \"oh, but we also need...\" reactions."),
                        StudyTopic(id: "consulting_impl_obj5_q5", number: 55, question: "A consultant discovers during discovery that the client's current CRM process is undocumented and inconsistent across teams. What should the consultant do before designing the Salesforce solution?", answer: "Do not design until the current state is understood and agreed upon. Steps:"),
                        StudyTopic(id: "consulting_impl_obj5_q6", number: 56, question: "**Document the current state** as-is, even if it is inconsistent — capture what each team actually does.", answer: ""),
                        StudyTopic(id: "consulting_impl_obj5_q7", number: 57, question: "**Identify the desired future state** — work with stakeholders to agree on the standardized process Salesforce should support.", answer: ""),
                        StudyTopic(id: "consulting_impl_obj5_q8", number: 58, question: "**Gain alignment and sign-off** on the future-state process before any configuration begins.", answer: ""),
                        StudyTopic(id: "consulting_impl_obj5_q9", number: 59, question: "**Flag the risk** that inconsistent processes will require change management investment, not just technology deployment.", answer: "Designing a Salesforce solution on top of an undocumented, inconsistent process typically results in an equally inconsistent system and low adoption."),
                        StudyTopic(id: "consulting_impl_obj5_q10", number: 60, question: "A company presents a list of 30 feature requests for a Sales Cloud implementation. How should a consultant prioritize these use cases to define the MVP scope?", answer: "Use a structured prioritization framework:\n\n- MoSCoW: Categorize each request as Must Have (essential for go-live), Should Have (important but not blocking), Could Have (nice- Won't Have (out of scope for now).\n\n- Value vs. Effort matrix: Plot each request on a 2x2 grid. High value/low effort items are \"quick wins\" for Phase 1. High value/high effort items go to Phase 2 planning. Low value items are deprioritized.\n\n- Dependencies: Some features must come before others (e.g., you cannot do opportunity forecasting before opportunities are configured). Let dependencies shape sequencing.\n\n- Stakeholder alignment: Present the prioritized list to the executive sponsor for formal sign-off on MVP scope.\n\n- Document the backlog: Capture all 30 items so lower-priority requests are not lost — they form the Phase 2 roadmap.")
                    ]
                )
            ]
        ),

        // Practical Application of Sales Cloud Expertise (4 objectives, 51 topics)
        StudySection(
            id: "practical_app",
            title: "Practical Application of Sales Cloud Expertise",
            color: Color(red: 0.55, green: 0.35, blue: 0.75),
            lightColor: Color(red: 0.94, green: 0.90, blue: 0.98),
            icon: "wrench.and.screwdriver.fill",
            objectives: [
                StudyObjective(
                    id: "practical_app_obj1",
                    title: "Given a set of requirements, construct an end-to-end sales process within Salesforce that supports the business from Lead to Opportunity to Quote to Close",
                    topics: [
                        StudyTopic(id: "practical_app_obj1_q1", number: 61, question: "What happens to lead field values when a lead is converted in Salesforce?", answer: "When a lead is converted, Salesforce creates (or matches to existing) a Contact, Account, and optionally an Opportunity. Standard lead field values are mapped to corresponding fields on those objects automatically by Salesforce's default field mapping. For example, Lead First/Last Name maps to Contact Name, Lead Company maps to Account Name, Lead Phone maps to Contact Phone.\n\nFields with no default mapping are not transferred unless a consultant creates a custom field mapping. The original Lead record is marked as Converted and remains in the system (visible to admins and via reports) but is no longer editable as an active lead."),
                        StudyTopic(id: "practical_app_obj1_q2", number: 62, question: "How can a consultant map custom lead fields to contact, account, and opportunity fields during lead conversion?", answer: "In Setup, navigate to Object Manager > Lead > Lead Fields, select the custom field, and use the \"Map Lead Fields\" button to map it to a corresponding custom field on the Contact, Account, or Opportunity object. The data type of the lead field and the target field must be compatible (e.g., Text to Text, Picklist to Picklist). Fields must exist on both objects before the mapping can be created. This mapping is applied every time a lead is converted — ensuring custom data travels with the lead."),
                        StudyTopic(id: "practical_app_obj1_q3", number: 63, question: "A company uses Web-to-Lead to capture inbound inquiries from its website. What are the configuration requirements, default behavior, and daily submission limits a consultant should be aware of?", answer: "Configuration: Enable Web-to-Lead in Setup, generate the HTML form, add the generated code to the website. Optionally configure a default lead creator, default lead source, and a \"Thank You\" redirect URL.\n\nDefault behavior: Submissions create Lead records automatically. Lead assignment rules fire immediately if configured. If no assignment rule matches, the lead is assigned to the default lead owner set in Web-to-Lead settings.\n\nLimits:\n\n- 500 leads per day by default (Salesforce processes excess submissions and queues them).\n\n- If the daily limit is exceeded, excess submissions are sent to the Default Lead Creator and Salesforce notifies the org admin.\n\n- Spam protection: Salesforce does not provide native CAPTCHA — a consultant should recommend adding Google reCAPTCHA or similar to the web form."),
                        StudyTopic(id: "practical_app_obj1_q4", number: 64, question: "A company wants to automatically route Web-to-Lead submissions to the correct rep based on lead source, geography, and product interest. Which Salesforce features support this, and what is their order of evaluation?", answer: "Lead Assignment Rules are the primary feature. Multiple rule entries are evaluated in order from top to bottom; the first matching entry wins. Each entry specifies criteria (e.g., Lead Source = \"Web\", State = \"California\") and assigns the lead to a specific user or queue.\n\nOrder of operations:"),
                        StudyTopic(id: "practical_app_obj1_q5", number: 65, question: "Web-to-Lead submits the record.", answer: ""),
                        StudyTopic(id: "practical_app_obj1_q6", number: 66, question: "Lead Assignment Rule entries are evaluated sequentially.", answer: ""),
                        StudyTopic(id: "practical_app_obj1_q7", number: 67, question: "The first matching entry assigns the lead to a user or queue.", answer: ""),
                        StudyTopic(id: "practical_app_obj1_q8", number: 68, question: "If no rule entry matches, the lead is assigned to the default Web-to-Lead owner.", answer: "For complex routing (e.g., lead score-based routing requiring a calculated value), a Flow triggered on Lead creation can complement or replace assignment rules with more sophisticated logic."),
                        StudyTopic(id: "practical_app_obj1_q9", number: 69, question: "What are the differences between opportunity stages and sales processes in Salesforce?", answer: "Opportunity Stages are the individual picklist values (e.g., Prospecting, Proposal, Negotiation, Closed Won) that represent where a deal is in the sales cycle. They are configured at the org level with associated Probability and Forecast Category values.\n\nSales Processes are subsets of opportunity stages grouped together to represent a specific type of sales motion. A Sales Process might include only 4 of 8 available stages, tailored for a particular product line or deal type.\n\nIn summary: stages are the building blocks; sales processes are curated selections of those stages applied to specific scenarios."),
                        StudyTopic(id: "practical_app_obj1_q10", number: 70, question: "How are opportunity stages and sales processes related to record types in Salesforce?", answer: "A Record Type on the Opportunity object is assigned one Sales Process. When a rep creates an opportunity and selects a record type, only the stages belonging to that record type's associated Sales Process appear in the Stage picklist. This allows the same org to support multiple distinct stage progressions (e.g., \"New Business\" record type uses a 7-stage process; \"Renewal\" record type uses a 4-stage process) without showing all stages to all reps."),
                        StudyTopic(id: "practical_app_obj1_q11", number: 71, question: "A company wants to ensure that every converted lead creates an opportunity with a specific record type and populates required fields automatically. How should a consultant configure this in Salesforce?", answer: "There is no native setting to force a specific Opportunity Record Type at lead conversion — the conversion screen shows a record type dropdown if multiple types exist. Options:\n\n- Flow on Lead Conversion: A Record-Triggered Flow fires after conversion, detects the newly created Opportunity, and updates the Record Type and pre-populates required fields based on lead field values.\n\n- Lead Conversion defaults: Set the org's default Opportunity Record Type so that the most common type is pre-selected at conversion.\n\n- Validation Rule on Opportunity: Prevent saving an opportunity created at conversion if required fields are blank, forcing the rep to complete them.\n\nThe Flow approach is the most robust for automating both the record type assignment and field population."),
                        StudyTopic(id: "practical_app_obj1_q12", number: 72, question: "A company needs to track multiple contacts associated with a single opportunity in different roles (economic buyer, technical buyer, champion). Which Salesforce feature supports this?", answer: "Opportunity Contact Roles. Each Contact associated with the opportunity is linked via a Contact Role record that specifies their role in the deal (Economic Buyer, Technical Buyer, Champion, Decision Maker, etc.). The primary contact is flagged as the Primary Contact Role.\n\nContact Roles can be made required via configuration or validation, and they appear in the Contact Roles related list on the Opportunity. This feature is critical for complex B2B sales where multiple stakeholders influence a purchasing decision."),
                        StudyTopic(id: "practical_app_obj1_q13", number: 73, question: "A sales team wants opportunity stages to enforce exit criteria before reps can advance to the next stage. Which Salesforce features support this requirement?", answer: "- Validation Rules: Trigger when a rep attempts to save a record with a new stage value. Check that required fields or conditions are met before allowing the stage change.\n\n- Path with Validation: Use the Path component configured on the Opportunity page to display stage-specific guidance and key fields. Path itself does not enforce — it guides — but combined with validation rules it creates a complete gating mechanism.\n\n- Screen Flow: A flow launched from the stage field or a button can walk reps through required fields at each stage transition before saving.\n\nValidation Rules are the most direct enforcement mechanism; Path adds UX guidance."),
                        StudyTopic(id: "practical_app_obj1_q14", number: 74, question: "A company wants reps to follow a guided selling path with different questions at each opportunity stage. Which Salesforce feature best supports this?", answer: "Path (Sales Path). It is configured on the Opportunity record page and displays stage-by-stage guidance including:\n\n- Key fields the rep should complete at that stage.\n\n- Guidance for Success text (configurable tips, checklists, or questions to consider).\n\n- A visual progress indicator across stages.\n\nPath is declaratively configured in Setup (Path Settings), tied to a specific record type and field (Stage), and displayed via the Path component on Lightning record pages. For more complex branching questionnaires, a Screen Flow embedded on the record page provides step-by-step prompts."),
                        StudyTopic(id: "practical_app_obj1_q15", number: 75, question: "A company generates quotes in Salesforce and syncs them to opportunities. What is the impact on opportunity amount and line items when a quote is synced?", answer: "When a Quote is synced to an Opportunity:\n\n- The Opportunity's Amount field becomes read-only and is automatically calculated from the Quote's line item totals (sum of Quote Line Items).\n\n- The Opportunity's Products (Opportunity Line Items) are replaced by the Quote Line Items — they stay in sync with the Quote.\n\n- Changes to the Quote (adding products, changing prices, applying discounts) automatically update the Opportunity Amount.\n\n- Only one Quote can be synced at a time. To sync a different Quote, you must first unsync the current one.\n\nUnsyncing a Quote leaves the Opportunity Amount at its last synced value but makes it editable again."),
                        StudyTopic(id: "practical_app_obj1_q16", number: 76, question: "A company requires that all deals above $50,000 go through a discount approval process before the quote is sent to the customer. How should a consultant design this in Salesforce?", answer: "Use Approval Processes on the Quote or Opportunity object:\n\n- Trigger criteria: Quote Total or Opportunity Amount > $50,000.\n\n- Approval steps: Route to the rep's manager, then to Sales VP if the discount exceeds a secondary threshold.\n\n- Lock record on submission: Prevent edits to the Quote/Opportunity while approval is pending.\n\n- Approval actions: On approval, set a custom field (e.g., \"Approved for Send\" = True) that a validation rule checks before the rep can mark the quote as \"Sent.\"\n\n- Rejection actions: Notify the rep, unlock the record, and allow revision.\n\nFor more complex multi-level approval logic, a Flow-based approval (using the newer Flow Orchestration or custom flow) can replace the standard approval process.")
                    ]
                ),
                StudyObjective(
                    id: "practical_app_obj2",
                    title: "Given a set of business requirements, identify the appropriate security model (sharing rules, role hierarchy, Account Teams, Opportunity Teams, permission sets, permission set groups)",
                    topics: [
                        StudyTopic(id: "practical_app_obj2_q1", number: 77, question: "What is the difference between Opportunity Teams and Account Teams in Salesforce?", answer: "Opportunity Teams: A team of users who collaborate on a specific Opportunity. Each member can have a different Opportunity Team role and access level (Read Only or Read/Write) to that opportunity. Teams are configured per opportunity and do not automatically apply to other records.\n\nAccount Teams: A team of users who collaborate on a specific Account. Members receive access to the Account and optionally to related Contacts, Cases, and Opportunities associated with the account. Teams are configured per account and can be set as a default team for a user.\n\nThe key distinction: Opportunity Teams are deal-level; Account Teams are relationship-level."),
                        StudyTopic(id: "practical_app_obj2_q2", number: 78, question: "When should a consultant recommend Opportunity Teams versus Account Teams?", answer: "Use Opportunity Teams when collaboration is deal-specific — a solution engineer, a legal reviewer, and an AE work together only on one particular deal. The team disbands or changes after the deal closes.\n\nUse Account Teams when collaboration is relationship-level — a dedicated account team (AE, CSM, Sales Ops) manages an account across all its opportunities, cases, and contacts over time. Account Teams are also better when consistent visibility across all account-related records is needed for multiple users."),
                        StudyTopic(id: "practical_app_obj2_q3", number: 79, question: "A company's OWD for Opportunities is Private, but sales managers need to view all opportunities owned by their direct reports. What is the correct configuration?", answer: "The Role Hierarchy provides this access automatically. In Salesforce, users in a higher role always have Read (and optionally Edit) access to records owned by users in subordinate roles, regardless of OWD, as long as the \"Grant Access Using Hierarchies\" setting is enabled (it is enabled by default for standard objects).\n\nSo the correct configuration is: place sales managers in a parent role above their direct reports in the role hierarchy. No sharing rule is needed — the hierarchy does the work."),
                        StudyTopic(id: "practical_app_obj2_q4", number: 80, question: "A company wants regional sales managers to see all opportunities in their region but not other regions. Reps should see only their own. Which security configuration achieves this?", answer: "- OWD for Opportunities: Private (reps see only their own by default).\n\n- Role Hierarchy: Each region has a manager role above its rep roles. The hierarchy gives managers visibility into their direct reports' records.\n\n- No cross-region sharing rules: Managers from other regions are in separate hierarchy branches and do not inherit each other's records.\n\nThis is achieved purely through role hierarchy structure with no sharing rules required. If there are edge cases (e.g., a regional manager needs to see accounts owned by reps who report to a peer manager), a criteria-based sharing rule can be added as a targeted expansion."),
                        StudyTopic(id: "practical_app_obj2_q5", number: 81, question: "A company wants to grant access to specific features (e.g., Export Reports, Manage Public List Views) to a subset of sales reps without changing their profile. What is the recommended approach?", answer: "Permission Sets. Create a permission set containing only the desired permissions (Export Reports, Manage Public List Views), then assign it to the specific users who need it. This follows the principle of least privilege and avoids broadening the profile for all users who share it.\n\nProfiles define the baseline; permission sets are additive. This is the Salesforce-recommended approach over cloning and modifying profiles."),
                        StudyTopic(id: "practical_app_obj2_q6", number: 82, question: "What are permission set groups, and when should a consultant use them instead of individual permission sets?", answer: "A Permission Set Group bundles multiple permission sets into a single assignable unit. Assigning the group grants all included permission sets at once, simplifying management.\n\nUse permission set groups when:\n\n- A role or persona requires multiple permission sets (e.g., an \"Enterprise AE\" needs 5 different permission sets).\n\n- You want to manage persona-level access as one entity rather than assigning 5 individual sets to hundreds of users.\n\n- You want to use muting permission sets to suppress specific permissions from within the group without modifying the underlying permission sets.\n\nThey are particularly valuable in complex orgs with many personas and layered permission structures."),
                        StudyTopic(id: "practical_app_obj2_q7", number: 83, question: "A company wants to grant a cross-functional team temporary access to a set of strategic accounts without changing the org-wide default or role hierarchy. What is the best approach?", answer: "Manual Sharing (Share button on individual records) for a small number of accounts, or Criteria-Based Sharing Rules if the strategic accounts share a common field value (e.g., a \"Strategic Account\" checkbox = True).\n\nFor truly temporary access, a Salesforce Flow can create manual share records programmatically and a scheduled job can remove them after a defined period.\n\nAccount Teams are also a strong option — add the cross-functional members to each strategic account's team with the appropriate access level, and remove them when the engagement ends."),
                        StudyTopic(id: "practical_app_obj2_q8", number: 84, question: "A company uses a partner channel and wants partner reps to see only their own accounts and opportunities in a Salesforce org shared with internal reps. How should the security model be structured?", answer: "- Experience Cloud (Partner Community): Partner reps should access Salesforce via a Partner Community portal, not the full Salesforce org. This limits their access to only what is exposed in the community.\n\n- OWD: Set Accounts and Opportunities to Private.\n\n- Role Hierarchy: Create a partner role hierarchy beneath the internal hierarchy, with a Partner Account Manager at the top.\n\n- Sharing rules or record ownership: Partner reps own only their accounts and opportunities, so OWD Privacy limits their view naturally.\n\n- Portal license: Partner users are assigned Partner Community or Partner Community Login licenses, which restrict access to internal data and internal users' records.\n\nThe community layer is the critical isolation mechanism."),
                        StudyTopic(id: "practical_app_obj2_q9", number: 85, question: "A company wants to implement Enterprise Territory Management. How does territory assignment affect opportunity visibility, and what is the relationship between territory membership and the role hierarchy?", answer: "Opportunity visibility via ETM: When an Account is assigned to a Territory, all Opportunities associated with that Account become visible to all users in that territory (including the territory's parent territories in the territory hierarchy). This grants access independent of opportunity ownership or role hierarchy position.\n\nRelationship to role hierarchy: ETM territory hierarchies are separate from the role hierarchy. A territory manager in ETM gains visibility through the territory model, not because they are above the opportunity owner in the role hierarchy. The two systems can coexist — a user can gain access to a record through either the role hierarchy OR a territory assignment.\n\nThis is important because it means ETM can grant access to records a user would not reach through the role hierarchy alone."),
                        StudyTopic(id: "practical_app_obj2_q10", number: 86, question: "When are sharing rules insufficient to meet a complex data access requirement, and what alternatives should a consultant consider?", answer: "Sharing rules are insufficient when:\n\n- Access requirements are user-specific or dynamic (e.g., \"grant access only to the user listed in the 'Partner Rep' field on the account\") — sharing rules work on role, group, or territory membership, not individual field values.\n\n- Access needs to be granted and revoked automatically based on changing conditions.\n\n- Access requirements involve complex multi-object logic.\n\nAlternatives:\n\n- Apex Managed Sharing: Write Apex code to create Share records programmatically with full control over timing and conditions.\n\n- Account/Opportunity Teams: Dynamically add/remove team members via Flow.\n\n- Territory Management: For geo/product-based access patterns.\n\n- External Sharing via Experience Cloud: For partner/customer access scenarios.")
                    ]
                ),
                StudyObjective(
                    id: "practical_app_obj3",
                    title: "Outline the capabilities, use cases, and design considerations when implementing Opportunity Products, Products, Price Books, Quotes, and the impact of multi-currency",
                    topics: [
                        StudyTopic(id: "practical_app_obj3_q1", number: 87, question: "What happens to the Opportunity Amount field when opportunity line items exist?", answer: "Once Products (Opportunity Line Items) are added to an Opportunity, the Amount field becomes read-only and is calculated automatically as the sum of all line item totals (Quantity x Sales Price for each line item). It can no longer be manually edited by the rep. If all line items are removed, the Amount field becomes editable again. This behavior is a key point to communicate to reps and stakeholders who are used to manually entering opportunity amounts."),
                        StudyTopic(id: "practical_app_obj3_q2", number: 88, question: "A company sells the same product at different prices to different customer segments. How should a consultant configure this using Salesforce Products and Price Books?", answer: "Create a single Product record for the item, then add it to multiple Price Books with different unit prices:\n\n- Standard Price Book: The default price.\n\n- \"Enterprise Customers\" Price Book: A lower negotiated price.\n\n- \"SMB Customers\" Price Book: A different price tier.\n\nWhen a rep creates an Opportunity, they select the applicable Price Book. The products in that price book display at the correct price for that customer segment. This avoids creating duplicate product records and keeps catalog management clean."),
                        StudyTopic(id: "practical_app_obj3_q3", number: 89, question: "What is the impact of enabling Advanced Currency Management (dated exchange rates) in Salesforce?", answer: "Advanced Currency Management (ACM) replaces static exchange rates with dated exchange rates — different exchange rates are stored for different time periods. When reporting on opportunity amounts, Salesforce uses the exchange rate in effect on the opportunity's Close Date rather than the current rate.\n\nImpact:\n\n- Roll-up summary fields on accounts/opportunities and certain other currency fields use dated rates for historical accuracy.\n\n- Cannot be disabled once enabled without Salesforce Support involvement.\n\n- Not compatible with some features: Einstein Forecasting, certain Flow currency conversion functions, and some third-party integrations may not support dated exchange rates."),
                        StudyTopic(id: "practical_app_obj3_q4", number: 90, question: "When is it appropriate to use Advanced Currency Management in Salesforce?", answer: "Use ACM when:\n\n- The company operates in multiple currencies and historical revenue reporting accuracy is critical (e.g., finance needs to see Q3 pipeline in USD using the exchange rates from Q3, not today's rate).\n\n- Deal values or forecasts would be distorted by rate fluctuations if static rates are used.\n\n- The company's finance team requires GAAP-compliant historical currency translation.\n\nDo not use ACM if the org relies heavily on features that are incompatible with it, or if currency fluctuation is not material to the business."),
                        StudyTopic(id: "practical_app_obj3_q5", number: 91, question: "A company operates in 15 countries with different currencies. A sales manager wants to see all opportunities in USD for rollup reporting. What configuration is required and what are the limitations?", answer: "Configuration:\n\n- Enable Multi-Currency in the org.\n\n- Set USD as the corporate (default) currency.\n\n- Add all 15 country currencies with their exchange rates.\n\n- Each opportunity is created in the rep's local currency. Salesforce automatically converts amounts to the corporate currency (USD) for rollup reporting using the stored exchange rate.\n\nLimitations:\n\n- If using standard currency management (static rates), all conversions use the current rate — historical opportunities are retroactively recalculated when rates change.\n\n- If using ACM, the Close Date rate is used, which is more accurate but adds complexity.\n\n- Currency fields in formula fields and some roll-up summaries may not convert consistently — test thoroughly.\n\n- Reports show converted amounts in the user's personal currency setting, not always USD unless the user's currency is set to USD."),
                        StudyTopic(id: "practical_app_obj3_q6", number: 92, question: "What happens to the opportunity amount when a synced quote is updated with new products or discounts?", answer: "When a Quote is synced to an Opportunity, the Opportunity Amount is automatically updated whenever the Quote is modified. Adding a product, removing a line item, or changing a discount on the synced Quote immediately recalculates the Quote Total, which flows to the Opportunity Amount. The opportunity amount remains read-only while a Quote is synced. Only the synced Quote can drive the Opportunity Amount — changes to other (unsynced) Quotes on the same Opportunity have no effect."),
                        StudyTopic(id: "practical_app_obj3_q7", number: 93, question: "A company wants reps to add products to opportunities and generate a PDF quote from within Salesforce. What are the steps and considerations for enabling this workflow?", answer: "Steps:"),
                        StudyTopic(id: "practical_app_obj3_q8", number: 94, question: "Enable **Products and Price Books** and add the product catalog.", answer: ""),
                        StudyTopic(id: "practical_app_obj3_q9", number: 95, question: "Enable **Quotes** in Setup.", answer: ""),
                        StudyTopic(id: "practical_app_obj3_q10", number: 96, question: "Add the Quotes related list and the Quote Line Items related list to Opportunity page layouts.", answer: ""),
                        StudyTopic(id: "practical_app_obj3_q11", number: 97, question: "Reps add Products to the Opportunity, then create a Quote (which inherits the line items).", answer: ""),
                        StudyTopic(id: "practical_app_obj3_q12", number: 98, question: "Configure a **Quote Template** (via the Quote Templates setup) for the PDF layout.", answer: ""),
                        StudyTopic(id: "practical_app_obj3_q13", number: 99, question: "Reps generate the PDF from the Quote record using the \"Generate Document\" button and can email it directly.", answer: "Considerations: Quote Templates use a custom markup language (similar to Visualforce) for advanced formatting. For complex CPQ scenarios, native Quotes may be insufficient — Salesforce CPQ (Revenue Cloud) provides a more powerful quoting engine."),
                        StudyTopic(id: "practical_app_obj3_q14", number: 100, question: "What are the design considerations when implementing Quotes in Salesforce, particularly around syncing quotes to opportunity line items?", answer: "- Only one Quote can be synced at a time: Design a clear workflow for how reps handle multiple quote versions (e.g., name conventions, archive old versions before creating a new one).\n\n- Syncing replaces Opportunity Products: When you sync a Quote, its line items replace the Opportunity's existing line items. Communicate this to reps.\n\n- Unsyncing leaves Amount static: Once unsynced, the Amount is not automatically updated if the rep changes line items manually on the opportunity.\n\n- Approval on Quote vs. Opportunity: Decide where the approval process lives — on the Quote (pre-send approval) or Opportunity (deal approval). Avoid duplicating approval logic across both.\n\n- Quote template complexity: Native Quote Templates are limited. For pixel-perfect PDFs, consider a third-party document generation tool or Salesforce CPQ."),
                        StudyTopic(id: "practical_app_obj3_q15", number: 101, question: "A company has a catalog of 10,000 SKUs. What design considerations should a consultant apply when configuring the product and price book structure to maintain usability for reps?", answer: "- Product families: Use the Product Family picklist to group SKUs so reps can filter the product search by category.\n\n- Product search and filtering: Reps use the product selector search on opportunities — ensure product names and codes are consistent and searchable.\n\n- Multiple price books: Split the catalog into relevant price books so reps only see the products applicable to their deals (e.g., \"North America Hardware\" price book vs. \"EMEA Software\" price book). This reduces the search pool.\n\n- Active/inactive status: Deactivate discontinued products rather than deleting them to preserve historical line item data.\n\n- Product descriptions: Populate the Description field to help reps distinguish similar products without needing to leave Salesforce.\n\n- Consider Salesforce CPQ: At 10,000 SKUs with likely complex pricing rules, native Products/Price Books may create usability challenges. CPQ's product rules, bundles, and guided selling features are purpose-built for large catalogs.")
                    ]
                ),
                StudyObjective(
                    id: "practical_app_obj4",
                    title: "Given a set of requirements, determine how to support different business and sales process scenarios for Campaigns, Leads, and Opportunities",
                    topics: [
                        StudyTopic(id: "practical_app_obj4_q1", number: 102, question: "What is the purpose of the Lead Status field, and how should a consultant configure it to differentiate between marketing-qualified and sales-qualified leads in the lead lifecycle?", answer: "Lead Status tracks where a lead is in the qualification funnel. It is the primary field used to signal handoffs between teams and trigger assignment or automation.\n\nRecommended configuration for MQL/SQL differentiation:\n\n- New: Unworked, just created.\n\n- MQL (Marketing Qualified Lead): Lead score or behavior threshold met; marketing hands off to sales.\n\n- SAL (Sales Accepted Lead): SDR has reviewed and accepted the lead as worth working.\n\n- SQL (Sales Qualified Lead): SDR has confirmed budget, authority, need, and timeline — ready to convert.\n\n- Working: Rep actively engaged.\n\n- Converted: Lead converted to Contact/Account/Opportunity.\n\n- Disqualified: Not a valid prospect; include a sub-categorization field for reason.\n\nClear status definitions ensure alignment between marketing and sales on what constitutes a qualified lead."),
                        StudyTopic(id: "practical_app_obj4_q2", number: 103, question: "What are the considerations for using lead queues versus assignment rules for distributing inbound leads to sales reps?", answer: "Lead Queues hold leads until a rep (or manager) manually claims them. Best for:\n\n- Round-robin distribution managed by a manager.\n\n- Teams that want reps to self-select leads based on their capacity.\n\n- Scenarios where no automated assignment logic exists.\n\nLead Assignment Rules automatically assign leads to a specific user or queue based on criteria. Best for:\n\n- Automated, criteria-driven routing (by geography, product, lead source, score).\n\n- Consistent, fast lead response without manual intervention.\n\n- Enforcing SLAs (combined with escalation rules or Flows).\n\nMost production implementations use assignment rules routing to queues, which combines the benefits of automated criteria-based routing with team-level visibility of unworked leads."),
                        StudyTopic(id: "practical_app_obj4_q3", number: 104, question: "A company requires that duplicate leads be identified and merged before conversion. Which Salesforce features support duplicate management for leads?", answer: "- Matching Rules: Define the logic for identifying potential duplicates (e.g., leads with the same email address, or same first name + last name + company). Salesforce includes standard matching rules out of the box.\n\n- Duplicate Rules: Define what happens when a potential duplicate is detected — Alert (warn the user), Block (prevent saving), or Report (log silently). Configured to run on Lead create and/or edit.\n\n- Duplicate Management reports: The \"Potential Duplicates\" report surfaces records flagged by duplicate rules for review and manual merge.\n\n- Merge Leads: From a Lead record, use the \"Find Duplicates\" button or the duplicate component to identify and merge up to 3 leads at a time, selecting which field values to retain."),
                        StudyTopic(id: "practical_app_obj4_q4", number: 105, question: "A company wants to automatically assign inbound web-to-lead submissions to the appropriate rep based on territory, product interest, and lead score. Which Salesforce feature handles this assignment logic?", answer: "Lead Assignment Rules are the primary tool. Each rule entry evaluates criteria (Lead Source, Product Interest field, State/Country, Lead Score) in priority order, assigning the lead to the matching user or queue.\n\nHowever, Lead Score is typically calculated by a marketing automation tool (e.g., Pardot) and synced back to a field on the Lead — the assignment rule can then reference that field. For very complex routing (e.g., dynamic territory lookup or score-based round-robin), a Record-Triggered Flow on Lead creation provides more sophisticated logic than assignment rules alone."),
                        StudyTopic(id: "practical_app_obj4_q5", number: 106, question: "What is the difference between Lead Source on a Lead record and campaign influence on an Opportunity?", answer: "Lead Source is a picklist field on the Lead (and Contact/Opportunity) that captures the original channel through which the lead was generated (e.g., Web, Event, Referral). It is a single-value attribution — it records only the first (or last) touch source.\n\nCampaign Influence is a related list on the Opportunity that tracks all campaigns that had a Campaign Member record for the associated Contact before the Opportunity was created or within a defined lookback window. It supports multi-touch attribution and can apply influence models (first touch, last touch, even distribution, or Einstein AI-driven).\n\nLead Source answers \"where did this lead originally come from?\" Campaign Influence answers \"which marketing activities contributed to winning this deal?\""),
                        StudyTopic(id: "practical_app_obj4_q6", number: 107, question: "When does Lead Source versus campaign influence matter for reporting?", answer: "Lead Source matters when:\n\n- Reporting on lead generation volume by channel (how many leads came from trade shows vs. web vs. referrals).\n\n- Quick, single-attribute campaign ROI tracking where multi-touch complexity is not needed.\n\nCampaign Influence matters when:\n\n- Multiple marketing touches occur before a deal closes and you need to understand which campaigns contributed.\n\n- Marketing wants to prove revenue influence, not just lead generation.\n\n- The company uses sophisticated attribution models to allocate marketing budget.\n\nFor most B2B companies with long sales cycles, Campaign Influence provides more meaningful ROI data than Lead Source alone."),
                        StudyTopic(id: "practical_app_obj4_q7", number: 108, question: "A company uses campaigns to track event attendance, email responses, and web form submissions. How should campaign member statuses be configured to support meaningful reporting?", answer: "Campaign Member Statuses should reflect the actual engagement actions, not just \"Sent/Responded.\" Configure statuses that map to real interactions:\n\n- For an event: Invited, Registered, Attended, No Show, Cancelled.\n\n- For an email campaign: Sent, Opened, Clicked, Responded, Unsubscribed.\n\n- For a web form: Submitted (mark as \"Responded\" = True to count in campaign statistics).\n\nMark the statuses that represent meaningful engagement as \"Responded = True\" — this drives the \"Responses\" count in Campaign statistics and ROI reporting. Generic \"Responded\" statuses lose the granularity needed to measure engagement quality."),
                        StudyTopic(id: "practical_app_obj4_q8", number: 109, question: "A company wants to track which marketing campaigns influenced a closed deal, even if a lead was touched by multiple campaigns. Which Salesforce feature supports multi-touch campaign attribution?", answer: "Campaign Influence (with the Customizable Campaign Influence model). It automatically creates Campaign Influence records on an Opportunity for each campaign that had a Campaign Member from the associated Contact within the attribution window (configurable lookback period).\n\nEinstein Attribution (if licensed) uses AI to assign influence percentages based on historical patterns rather than a manual model.\n\nThe Primary Campaign Source field on the Opportunity captures a single designated campaign for simple attribution, but Campaign Influence is the feature that supports true multi-touch tracking."),
                        StudyTopic(id: "practical_app_obj4_q9", number: 110, question: "A company wants to use campaign hierarchies to roll up ROI metrics from child campaigns (individual events) to a parent campaign (annual event series). How should this be configured and what are the limitations?", answer: "Configuration:\n\n- Create a parent Campaign record (e.g., \"Annual Sales Summit 2025\").\n\n- Create child Campaign records for each individual event and set the \"Parent Campaign\" field to the parent record.\n\n- Child campaigns' statistics (Leads, Contacts, Opportunities, Revenue) automatically roll up to the parent's Hierarchy fields (e.g., \"Total Opportunities in Hierarchy,\" \"Total Value Won Opportunities in Hierarchy\").\n\nLimitations:\n\n- Hierarchy rollup fields are read-only system-calculated fields — you cannot create custom rollup fields that aggregate up the hierarchy natively.\n\n- Campaign hierarchies support up to 5 levels of nesting.\n\n- The rollup fields aggregate all records in the hierarchy regardless of campaign status — there is no native way to filter the rollup (e.g., only count \"Attended\" members).\n\n- For more complex rollup analysis, reports with campaign hierarchy grouping or CRM Analytics are required."),
                        StudyTopic(id: "practical_app_obj4_q10", number: 111, question: "A company's sales process differs for new business opportunities versus renewal opportunities. How should a consultant configure Salesforce to support both processes?", answer: "- Two Sales Processes: Create a \"New Business\" Sales Process with stages like Prospecting, Qualification, Proposal, Negotiation, Closed Won/Lost. Create a \"Renewal\" Sales Process with stages like Renewal Review, Negotiation, Renewed, Churned.\n\n- Two Opportunity Record Types: Map \"New Business\" record type to the New Business Sales Process; map \"Renewal\" record type to the Renewal Sales Process.\n\n- Different Page Layouts: Each record type can have a distinct page layout showing relevant fields for each process (e.g., renewal date, contract value, churn reason).\n\n- Different Validation Rules: Use record type criteria in validation rules to enforce process-specific exit criteria only for the applicable type.\n\n- Separate reporting: Filter opportunity reports by record type to track new business pipeline and renewal pipeline independently.")
                    ]
                )
            ]
        ),

        // Data Management (3 objectives, 31 topics)
        StudySection(
            id: "data_mgmt",
            title: "Data Management",
            color: Color(red: 0.80, green: 0.40, blue: 0.20),
            lightColor: Color(red: 1.00, green: 0.94, blue: 0.88),
            icon: "externaldrive.fill",
            objectives: [
                StudyObjective(
                    id: "data_mgmt_obj1",
                    title: "Explain the use cases and considerations for data migrations and integrations",
                    topics: [
                        StudyTopic(id: "data_mgmt_obj1_q1", number: 112, question: "What are the differences between using Data Loader and the Data Import Wizard for a Sales Cloud data migration?", answer: "| | Data Import Wizard | Data Loader |\n\n|---|---|---|\n\n| Access | Browser-based, in Salesforce Setup | Desktop application (Windows/Mac) |\n\n| Supported objects | Limited (standard objects: Leads, Accounts, Contacts, Solutions, custom objects) | All standard and custom objects |\n\n| Max records per load | 50,000 | Up to 5 million per batch |\n\n| Upsert | No (insert and update only) | Yes (upsert using external ID) |\n\n| Bulk API | No | Yes (Bulk API for large volumes) |\n\n| Error logging | Basic in-app feedback | Detailed CSV error file |\n\n| Automation | No | Yes (command-line/scheduled) |"),
                        StudyTopic(id: "data_mgmt_obj1_q2", number: 113, question: "When should a consultant use Data Loader versus the Data Import Wizard for a Sales Cloud data migration?", answer: "Use Data Import Wizard when:\n\n- Loading fewer than 50,000 records of supported object types.\n\n- The user is non-technical and needs a simple, guided UI.\n\n- No upsert is needed.\n\nUse Data Loader when:\n\n- Loading more than 50,000 records.\n\n- Loading objects not supported by the Import Wizard (e.g., Opportunities, Activities).\n\n- Upsert with external IDs is required to avoid duplicates.\n\n- The load needs to be scheduled or scripted.\n\n- Detailed error logging for large loads is needed."),
                        StudyTopic(id: "data_mgmt_obj1_q3", number: 114, question: "What is the difference between a full data migration and a delta migration, and when is each approach appropriate?", answer: "Full migration: All records from the source system are migrated to Salesforce at once. The legacy system is cut off simultaneously. Best for: smaller data volumes, clean source data, or when a hard cutover is feasible.\n\nDelta migration: An initial full load is performed, and then only records created or modified after the cutover date are loaded subsequently to catch changes that occurred during the migration period. Best for: large data volumes where the migration takes weeks, or when the source system must remain live during a parallel-run period.\n\nThe delta approach requires tracking change timestamps in the source system and running one or more additional loads close to go-live."),
                        StudyTopic(id: "data_mgmt_obj1_q4", number: 115, question: "A company is migrating 5 years of opportunity history from a legacy CRM into Salesforce. What are the key considerations a consultant should address in the migration plan?", answer: "- Data mapping: Map all source fields to Salesforce fields. Identify gaps where source fields have no Salesforce equivalent (create custom fields if needed).\n\n- Data cleansing: Identify and resolve duplicates, blank required fields, and inconsistent values before the load.\n\n- Record types and stages: Map legacy deal stages to Salesforce opportunity stages and assign correct record types.\n\n- Historical ownership: Map legacy sales rep IDs to Salesforce User IDs. Departed reps need a placeholder owner or an inactive user record.\n\n- Related records: Opportunities require Account records to exist first — load accounts before opportunities.\n\n- Audit trail: Use \"Set Audit Fields\" (enabled via API for orgs with the appropriate permission) to preserve original Created Date and Last Modified Date.\n\n- Volume and performance: 5 years of history may be very large. Use Bulk API, consider batch loads, and test load times in sandbox first.\n\n- Archive vs. active records: Consider loading only recent/active opportunities in full detail and archiving older records in a lighter format."),
                        StudyTopic(id: "data_mgmt_obj1_q5", number: 116, question: "What are the considerations for preserving record ownership and historical audit trails when migrating data into Salesforce?", answer: "- Record ownership: The loading user becomes the default Owner unless you explicitly populate the OwnerId field in the import file. Map all legacy owners to their Salesforce User IDs before loading. For departed reps, either create inactive Salesforce users or reassign to their manager.\n\n- Created Date / Last Modified Date: By default, Salesforce sets these to the import date. To preserve legacy dates, enable \"Set Audit Fields upon Record Creation\" permission via the API or use a tool that supports audit field setting.\n\n- Created By / Last Modified By: Similarly requires the \"Update Records with Inactive Owners\" and \"Set Audit Fields\" permissions or API access.\n\n- History tracking: If field history tracking is enabled, it begins tracking changes after the record is created in Salesforce — it does not backfill legacy change history. Consider documenting legacy audit history externally if compliance requires it."),
                        StudyTopic(id: "data_mgmt_obj1_q6", number: 117, question: "During a data migration, a consultant discovers that the source data has inconsistent field formats and missing required fields. What should the consultant do before proceeding with the load?", answer: "Stop and cleanse before loading. Steps:"),
                        StudyTopic(id: "data_mgmt_obj1_q7", number: 118, question: "**Export and profile the source data**: Use Excel, Python, or a data quality tool to analyze the extent of inconsistencies (how many records are affected, which fields).", answer: ""),
                        StudyTopic(id: "data_mgmt_obj1_q8", number: 119, question: "**Cleanse in the source or a staging file**: Standardize formats (e.g., phone number formatting, date formats), fill in required fields where possible (e.g., default values, lookups to fix account names).", answer: ""),
                        StudyTopic(id: "data_mgmt_obj1_q9", number: 120, question: "**Document decisions**: Record what data quality rules were applied and any records that could not be cleansed (and why).", answer: ""),
                        StudyTopic(id: "data_mgmt_obj1_q10", number: 121, question: "**Load to sandbox first**: Test the cleaned file in sandbox before loading to production.", answer: ""),
                        StudyTopic(id: "data_mgmt_obj1_q11", number: 122, question: "**Do not load garbage data**: Loading bad data into Salesforce creates a worse problem than loading nothing — it pollutes the new system from day one.", answer: ""),
                        StudyTopic(id: "data_mgmt_obj1_q12", number: 123, question: "A company wants to integrate its ERP system with Salesforce to sync account and order data in near real time. What integration pattern should a consultant evaluate first?", answer: "Event-Driven (Real-Time) Integration via API. Options:\n\n- Salesforce REST/SOAP API: The ERP calls Salesforce's API when an account or order event occurs (e.g., order created), and Salesforce is updated in near real time.\n\n- Platform Events: Salesforce publishes or subscribes to platform events, allowing event-driven messaging between Salesforce and the ERP without tight coupling.\n\n- MuleSoft or middleware (iPaaS): For complex bi-directional sync with transformation logic, an integration platform (MuleSoft, Boomi, Jitterbit) sits between the ERP and Salesforce and handles mapping, error handling, and retry logic.\n\nEvaluate the ERP's API capabilities and the required latency first. Most enterprise ERPs (SAP, Oracle, NetSuite) have pre-built connectors for MuleSoft or AppExchange integration apps."),
                        StudyTopic(id: "data_mgmt_obj1_q13", number: 124, question: "A company wants to integrate a third-party marketing automation tool with Salesforce to sync leads and campaign data. What integration approach minimizes data duplication risk?", answer: "- Use the native connector if available: Most major MAPs (Pardot/Marketing Cloud Account Engagement, Marketo, HubSpot) have native Salesforce connectors that use matching and sync logic to link records by email address or Salesforce ID.\n\n- Establish Salesforce as the master for lead identity: Leads created in the MAP should be synced to Salesforce and assigned a Salesforce ID. Subsequent updates should use that ID to update the existing record rather than creating a new one.\n\n- Enable Salesforce Duplicate Management: Matching and duplicate rules in Salesforce catch any duplicates that slip through the integration.\n\n- Sync Campaign Members, not just Leads: Use Campaign Member records to track engagement without creating new lead records for every interaction.\n\n- Test deduplication logic in sandbox before go-live, using representative data from both systems.")
                    ]
                ),
                StudyObjective(
                    id: "data_mgmt_obj2",
                    title: "Given a scenario, outline the scalability implications of a solution",
                    topics: [
                        StudyTopic(id: "data_mgmt_obj2_q1", number: 125, question: "What are the implications of large data volumes (LDV) on sharing rule recalculation and report performance in Salesforce?", answer: "Sharing rule recalculation: When OWD settings or sharing rules are changed, Salesforce recalculates sharing for all affected records. With LDV, this recalculation can take hours or run asynchronously, during which time some records may be inaccessible or show incorrect access. Adding new sharing rules to an org with millions of records should be planned for a maintenance window.\n\nReport performance: Reports with no selective filters on indexed fields perform full table scans. With millions of records, reports can time out, return partial results, or fail entirely. Best practices: always filter by indexed fields (Owner, Created Date, Close Date), limit cross-object joins, and consider pre-aggregating data in CRM Analytics for large-volume reporting."),
                        StudyTopic(id: "data_mgmt_obj2_q2", number: 126, question: "A company plans to store 10 years of closed opportunity history in Salesforce and run reports across all years. What scalability implications should a consultant raise?", answer: "- Report timeouts: Unfiltered historical reports across 10 years of data are likely to timeout if the data volume is in the millions of records.\n\n- Sharing recalculation time: Any sharing model change will trigger a recalculation across all 10 years of records — this can be very slow.\n\n- Storage costs: Salesforce charges for data storage above included limits. 10 years of opportunity records with associated files, attachments, and related objects can be significant.\n\n- Index effectiveness: Queries on non-indexed fields become less selective with larger volumes, degrading performance.\n\n- Recommendation: Consider an archiving strategy — move records older than 3-5 years to an external data warehouse (e.g., AWS Redshift, Snowflake) or a Salesforce-native archive solution, with Salesforce retaining only the active and recent pipeline. CRM Analytics can blend Salesforce + external data for full historical reporting."),
                        StudyTopic(id: "data_mgmt_obj2_q3", number: 127, question: "A company has accounts with thousands of associated opportunities. What performance implications should a consultant consider for related list rendering and page load experience?", answer: "- Related list loading: By default, related lists load synchronously on the record page. An Account with 10,000+ opportunities will cause very slow page loads or timeouts.\n\n- Solutions:\n\n- Set related lists to load asynchronously (available in Lightning Experience).\n\n- Limit the number of columns and records displayed in the related list.\n\n- Use a list view or report instead of the related list for deep history.\n\n- Consider a custom LWC component with pagination for very large related lists.\n\n- Roll-up summary fields: Roll-up summaries on Account (summing opportunity amounts) recalculate on every related opportunity change — with thousands of records, this adds DML time and can trigger lock contention on the parent Account record."),
                        StudyTopic(id: "data_mgmt_obj2_q4", number: 128, question: "When is it appropriate to recommend an external data archiving strategy rather than storing all historical records in Salesforce?", answer: "Recommend external archiving when:\n\n- The org has millions of records and is approaching or has exceeded Salesforce storage limits.\n\n- Historical reports on old data are infrequent and can be served from an external data warehouse.\n\n- Regulatory requirements mandate long-term retention but not necessarily in the active transactional system.\n\n- Data is read-only reference data (e.g., closed deals from 5+ years ago) with no business process reason to remain in Salesforce.\n\n- Storage costs have become significant.\n\nExternal archiving solutions include Salesforce's own Data Archive (Backup & Archive), third-party tools (OwnBackup, Owndata), or direct export to a data warehouse with BI tooling for historical reporting.")
                    ]
                ),
                StudyObjective(
                    id: "data_mgmt_obj3",
                    title: "Discuss approaches for managing sales data quality in Salesforce",
                    topics: [
                        StudyTopic(id: "data_mgmt_obj3_q1", number: 129, question: "What is the purpose of matching rules in Salesforce, and how do they differ from duplicate rules?", answer: "Matching Rules define the logic for comparing records to identify potential duplicates. They specify which fields to compare (e.g., email, name, phone) and the matching algorithm (exact, fuzzy, begins with). Matching rules are the \"detection engine.\"\n\nDuplicate Rules define what happens when a match is found: alert the user with a warning, block the save entirely, or silently report the duplicate. Duplicate rules reference matching rules to determine what constitutes a duplicate. Duplicate rules are the \"action engine.\"\n\nYou need both: a matching rule to identify potential duplicates, and a duplicate rule to determine the response."),
                        StudyTopic(id: "data_mgmt_obj3_q2", number: 130, question: "What is the purpose of duplicate rules in Salesforce?", answer: "Duplicate rules control the system's response when a user attempts to create or edit a record that matchesas identified by a matching rule). Options:\n\n- Alert: Warn the user that a duplicate may exist but allow them to save.\n\n- Block: Prevent saving entirely until the duplicate is resolved.\n\n- Report only: Allow saving but log the duplicate for review (visible in the \"Duplicate Record Sets\" object).\n\nDuplicate rules can be configured separately for record creation vs. editing, and can be scoped to specific conditions (e.g., apply only when Lead Source = \"Web\")."),
                        StudyTopic(id: "data_mgmt_obj3_q3", number: 131, question: "How can a consultant use validation rules and required fields to enforce data quality without creating excessive friction for end users?", answer: "- Target high-value fields only: Only enforce data quality on fields that genuinely drive business decisions (stage, close date, amount, account). Avoid requiring every field.\n\n- Stage-gated requirements: Use validation rules that check required fields only when the opportunity advances to a specific stage, not on every save. This way, reps aren't blocked at early stages.\n\n- Clear error messages: Write validation rule error messages in plain language that tells the rep what to enter, not just that an error occurred.\n\n- Default values: Use default field values to pre-populate fields wherever reasonable, reducing the burden on the rep.\n\n- Picklists over free text: Where possible, replace free-text fields with picklists to enforce standardized values without extra clicks.\n\n- Path guidance: Use Path's \"Key Fields\" feature to visually highlight what needs to be entered at each stage, supplementing validation rules with UX prompts."),
                        StudyTopic(id: "data_mgmt_obj3_q4", number: 132, question: "What are the trade-offs between enforcing data quality at entry time (e.g., required fields, validation rules) versus enforcing it post-entry (e.g., data quality dashboards, batch updates)?", answer: "Entry-time enforcement (required fields, validation rules):\n\n- Pros: Prevents bad data from entering the system; highest data integrity.\n\n- Cons: Creates friction for reps; can slow down data entry; if rules are too aggressive, reps enter dummy values to bypass them.\n\nPost-entry enforcement (dashboards, batch updates):\n\n- Pros: No friction during entry; catches issues retrospectively; allows for process improvements over time.\n\n- Cons: Bad data exists in the system during the gap between entry and cleanup; requires manual or automated remediation; does not prevent the problem, only detects it.\n\nBest practice: Use entry-time enforcement for critical fields that are immediately needed (Close Date, Stage, Owner, Account) and post-entry monitoring for completeness tracking and ongoing quality improvement. Do not require every field at entry — save complexity for the most impactful fields."),
                        StudyTopic(id: "data_mgmt_obj3_q5", number: 133, question: "A company's opportunity records have inconsistent close dates and missing probability fields, making forecasting unreliable. What data quality measures should a consultant recommend?", answer: "- Validation rules: Require that Close Date is a future date for open opportunities. Block saves when Close Date is blank.\n\n- Probability field: If using standard Salesforce probability (linked to Stage), ensure each stage has a meaningful default probability set. If probability is manually overridden, add a validation or guidance message when probability is blank.\n\n- Path key fields: Add Close Date and Probability as key fields on the opportunity Path, prompting reps visually at each stage.\n\n- Manager-enforced review: Train managers to review and update close dates and probability in 1:1 pipeline reviews — behavioral enforcement is often more effective than technical enforcement.\n\n- Data quality dashboard: Build a report showing opportunities with close dates in the past or blank probability, visible to managers for weekly review.\n\n- Automated nudges: Use Flows to send a reminder notification to the rep and manager when an open opportunity's close date is in the past."),
                        StudyTopic(id: "data_mgmt_obj3_q6", number: 134, question: "A company wants to prevent reps from entering account names in inconsistent formats (e.g., 'Inc.' vs 'Incorporated'). Which Salesforce features help enforce data entry standards?", answer: "- Duplicate Rules with fuzzy matching: Fuzzy matching rules detect \"Acme Inc.\" and \"Acme Incorporated\" as potential duplicates and alert the rep to check before creating a new record.\n\n- Validation Rules: Prohibit specific patterns (e.g., block \"Inc.\" using REGEX validation) or enforce formatting standards.\n\n- Picklists or lookups instead of free text: If accounts are pre-existing, require reps to search for and select an existing Account record rather than typing a name — eliminating the free-text inconsistency problem at the source.\n\n- Third-party data enrichment tools: AppExchange tools like Dun & Bradstreet or ZoomInfo can standardize account names against a reference database.\n\n- Data stewardship process: Assign a data steward to periodically review and merge Account records with variant names."),
                        StudyTopic(id: "data_mgmt_obj3_q7", number: 135, question: "A company's legacy CRM has a large volume of stale lead records. What approach should a consultant recommend for improving lead data quality before migration?", answer: ""),
                        StudyTopic(id: "data_mgmt_obj3_q8", number: 136, question: "**Audit the source data**: Profile the lead records — how old are they? What percentage have valid email addresses? What is the lead status distribution?", answer: ""),
                        StudyTopic(id: "data_mgmt_obj3_q9", number: 137, question: "**Define freshness criteria**: Agree with the business on what makes a lead worth migrating (e.g., created within the last 2 years, or lead status not = \"Disqualified\").", answer: ""),
                        StudyTopic(id: "data_mgmt_obj3_q10", number: 138, question: "**Segment and purge**: Leads outside the freshness criteria should be archived in the legacy system (not migrated) or discarded, with business sign-off.", answer: ""),
                        StudyTopic(id: "data_mgmt_obj3_q11", number: 139, question: "**Enrich before migrating**: For leads worth keeping, use a data enrichment tool to fill in missing fields (job title, company size, email) before loading.", answer: ""),
                        StudyTopic(id: "data_mgmt_obj3_q12", number: 140, question: "**Standardize field values**: Normalize Lead Status values to match the Salesforce picklist. Resolve inconsistent Lead Source values.", answer: ""),
                        StudyTopic(id: "data_mgmt_obj3_q13", number: 141, question: "**Run through matching rules in sandbox**: Test the cleaned lead file in sandbox to see how many duplicates the matching rules detect before the production load.", answer: ""),
                        StudyTopic(id: "data_mgmt_obj3_q14", number: 142, question: "A company wants to measure and track data completeness scores across account and opportunity records over time. What approach should a consultant recommend?", answer: "- Formula fields: Create formula fields on Account and Opportunity that calculate a completeness score (e.g., count how many of 10 key fields are populated, divide by 10, multiply by 100 to get a percentage).\n\n- Reports: Build Summary reports on Accounts and Opportunities using the completeness score formula field. Group by Owner or Team to identify which reps or teams have the lowest completion rates.\n\n- Dashboards: Display completeness score trend over time using a dashboard subscribed to on a monthly basis (though trending requires storing historical snapshots, which may require external tools or a custom object for history).\n\n- Salesforce Adoption Dashboards: Salesforce's AppExchange provides free Adoption Dashboards that include data completeness metrics out of the box.\n\n- CRM Analytics: For true time-series completeness trending, CRM Analytics can store historical snapshots and visualize improvement over time.")
                    ]
                )
            ]
        ),

        // Predictive and Generative AI (2 objectives, 12 topics)
        StudySection(
            id: "ai",
            title: "Predictive and Generative AI",
            color: Color(red: 0.25, green: 0.55, blue: 0.70),
            lightColor: Color(red: 0.88, green: 0.95, blue: 0.98),
            icon: "brain.fill",
            objectives: [
                StudyObjective(
                    id: "ai_obj1",
                    title: "Understand what generative AI tools are available in Agentforce for Sales",
                    topics: [
                        StudyTopic(id: "ai_obj1_q1", number: 143, question: "What is the purpose of the Sales Call Summary feature in Agentforce for Sales, and what is required to enable it?", answer: "Sales Call Summary (Einstein Conversation Insights) automatically transcribes recorded sales calls and generates a structured summary including key discussion points, customer questions, action items, and next steps. It surfaces on the related Salesforce Activity record, eliminating manual note-taking.\n\nRequirements to enable:\n\n- A supported telephony integration or Salesforce Dialer (calls must be recorded and passed to Salesforce for transcription).\n\n- Einstein Conversation Insights license.\n\n- Einstein generative AI features enabled in Setup (Einstein Settings).\n\n- Call recording consent compliance with local laws (a critical legal consideration in many jurisdictions)."),
                        StudyTopic(id: "ai_obj1_q2", number: 144, question: "What generative AI capabilities does Agentforce for Sales provide for opportunity briefing and preparation before customer meetings?", answer: "Meeting Preparation / Opportunity Briefing: Agentforce can generate a pre-meeting briefing for a rep that summarizes:\n\n- Recent activity on the opportunity (emails, calls, meetings).\n\n- Key stakeholders and their roles.\n\n- Current stage, close date, and outstanding next steps.\n\n- Recent news or signals from connected data sources.\n\nThis is surfaced via Einstein Copilot (now Agentforce) on the Opportunity or Meeting record, allowing a rep to get a full deal context summary with a single prompt rather than manually reviewing 10 different records."),
                        StudyTopic(id: "ai_obj1_q3", number: 145, question: "A company wants to use AI to draft a follow-up email after a sales call that references key discussion points and proposed next steps. Which Sales Cloud generative AI feature addresses this?", answer: "Einstein Copilot (Agentforce) with the Draft Email action or Sales Email generation. After a call is logged (with a summary from Einstein Conversation Insights), the rep can prompt Agentforce to draft a follow-up email. Agentforce uses the call summary, the opportunity record, and the contact's context to generate a personalized email draft that the rep reviews and sends. This is accessed via the Copilot sidebar in Salesforce."),
                        StudyTopic(id: "ai_obj1_q4", number: 146, question: "A company wants sales reps to automatically generate a personalized email draft based on the opportunity record and recent activity. Which Agentforce for Sales feature supports this?", answer: "Einstein Sales Emails (part of Agentforce for Sales). Reps access it from the Activity composer or Email section on the Opportunity or Contact record. Clicking \"Draft with Einstein\" generates a personalized email using context from:\n\n- The Opportunity (stage, amount, close date, product).\n\n- Recent activities (last call summary, emails).\n\n- Contact information (name, role, company).\n\nThe rep can refine the draft before sending. This feature requires Einstein for Sales to be enabled and the user to have the appropriate permission set."),
                        StudyTopic(id: "ai_obj1_q5", number: 147, question: "A company wants an AI-powered agent to autonomously follow up with prospects after a demo, send tailored content, and schedule next steps. Which Agentforce capability supports this use case?", answer: "Agentforce Sales Development Representative (SDR) Agent (or the Agentforce Sales Agent). This is an autonomous AI agent that can:\n\n- Monitor triggers (e.g., demo completed, form submitted).\n\n- Draft and send personalized follow-up emails to prospects.\n\n- Respond to prospect replies within guardrails.\n\n- Schedule meetings by offering availability and booking on the rep's calendar.\n\n- Escalate to a human rep when the conversation requires it.\n\nThis agent operates within defined guardrails set by the admin (topic restrictions, tone guidelines, escalation rules), embodying Salesforce's \"humans in control\" model.")
                    ]
                ),
                StudyObjective(
                    id: "ai_obj2",
                    title: "Understand what predictive AI tools are available in Sales Cloud",
                    topics: [
                        StudyTopic(id: "ai_obj2_q1", number: 148, question: "What is Einstein Lead Scoring, how does it work, and what data does it use to generate scores?", answer: "Einstein Lead Scoring uses machine learning to assign each Lead a score from 1-99 representing the likelihood of conversion to an opportunity. It is trained on the org's own historical lead conversion data.\n\nHow it works: Einstein analyzes closed/converted leads and identifies patterns among leads that converted vs. those that did not. It then scores open leads based on those patterns.\n\nData used: Lead field values such as Lead Source, Industry, Company Size, Title, Geography, and behavioral signals (if connected to EAC or marketing data). The model is org-specific — it learns from your data, not a generic dataset.\n\nRequirement: A minimum volume of closed leads (approximately 1,000 converted and 1,000 not-converted leads) is needed to train the model reliably."),
                        StudyTopic(id: "ai_obj2_q2", number: 149, question: "A sales manager wants the CRM to score each open opportunity based on its likelihood to close. Which Sales Cloud Einstein feature provides this?", answer: "Einstein Opportunity Scoring. It assigns each open opportunity a score from 1-99 and displays the score on the opportunity record and list views. The score is accompanied by factors that are positively or negatively influencing it (e.g., \"No activity in 14 days\" or \"Rep has high win rate for this deal type\"). Managers can use scores to prioritize coaching and pipeline reviews."),
                        StudyTopic(id: "ai_obj2_q3", number: 150, question: "What is the difference between Einstein Opportunity Scoring and Einstein Forecasting?", answer: "Einstein Opportunity Scoring operates at the individual deal level. It scores each open opportunity on its likelihood to close and explains the contributing factors. It helps reps and managers identify which deals need attention.\n\nEinstein Forecasting operates at the aggregate/team level. It uses AI to predict the total revenue a rep, team, or organization will close in a given period, comparing the AI-predicted amount against the rep's manually submitted forecast. It identifies gaps between human judgment and AI prediction.\n\nThink of it as: Scoring = \"will this deal close?\" Forecasting = \"how much will the team close this quarter?\""),
                        StudyTopic(id: "ai_obj2_q4", number: 151, question: "When should a consultant recommend Einstein Opportunity Scoring versus Einstein Forecasting?", answer: "Recommend Einstein Opportunity Scoring when:\n\n- The primary need is helping reps prioritize which deals to focus on.\n\n- Managers need a quick visual indicator of deal health in pipeline reviews.\n\n- The sales cycle is long enough that early warning of at-risk deals is valuable.\n\nRecommend Einstein Forecasting when:\n\n- Sales leadership needs an AI-generated revenue prediction for the quarter to compare against rep-submitted forecasts.\n\n- There is concern that rep-submitted forecasts are biased (too optimistic or conservative).\n\n- The org wants to improve forecast accuracy using historical pattern recognition at the team/org level.\n\nBoth can be used simultaneously and complement each other."),
                        StudyTopic(id: "ai_obj2_q5", number: 152, question: "A company wants to surface the next-best action for each rep based on deal stage, recent activity, and buyer engagement. Which Sales Cloud Einstein feature provides this recommendation?", answer: "Einstein Next Best Action (NBA). An admin creates Recommendation records and Action Strategy flows that define what recommendations to surface and under what conditions. The NBA component on the Opportunity record evaluates the strategy at runtime and displays relevant action cards to the rep (e.g., \"Schedule an executive briefing,\" \"Send a ROI case study,\" \"Request procurement contact\").\n\nRecommendations can be based on Einstein Prediction fields, Opportunity data, and activity history. Reps accept or decline recommendations, and the system learns from those signals over time."),
                        StudyTopic(id: "ai_obj2_q6", number: 153, question: "A company wants to identify which accounts are most likely to churn or expand based on engagement signals and usage data. Which Einstein feature is most relevant?", answer: "Einstein Discovery (CRM Analytics) or Einstein Prediction Builder.\n\n- Einstein Prediction Builder: Allows admins to build a custom predictive model on the Account object using fields available in Salesforce. You can train a model to predict churn likelihood or expansion potential if those outcomes are tracked as historical fields.\n\n- Einstein Discovery: More powerful — can analyze large datasets, surface statistical drivers of churn or expansion, and provide prescriptive recommendations on what actions change the outcome. Requires CRM Analytics license.\n\nFor usage data from an external system (e.g., product usage telemetry), integrate that data into Salesforce first (via Data Streams in CRM Analytics), then build the prediction on the combined dataset."),
                        StudyTopic(id: "ai_obj2_q7", number: 154, question: "What are the data volume and quality prerequisites for enabling Einstein predictive features in Sales Cloud?", answer: "Minimum data volumes (approximate Salesforce guidelines):\n\n- Einstein Lead Scoring: ~1,000 converted leads and ~1,000 non-converted leads in the past 6 months-2 years.\n\n- Einstein Opportunity Scoring: ~200 won and ~200 lost opportunities in the past 2 years.\n\n- Einstein Forecasting: Sufficient historical closed opportunity data with quota records populated.\n\nData quality requirements:\n\n- Fields used by the model must be consistently populated — sparse or inconsistent data degrades model accuracy.\n\n- Historical depth: More historical data generally improves accuracy, but very old data that no longer reflects current sales behavior can introduce noise.\n\n- Outcome fields: Won/Lost or Converted/Not Converted designations must be accurate — if reps mark deals as Closed Lost incorrectly, the model learns the wrong patterns.\n\nEinstein displays a \"Model Health\" score in Setup to indicate whether data quality and volume are sufficient for reliable predictions.")
                    ]
                )
            ]
        )

    ]
}
